window.DIGEST_WEEKS=window.DIGEST_WEEKS||{};window.DIGEST_WEEKS["2026-06-01"]={"monday": "2026-06-01", "sunday": "2026-06-07", "iso_year": 2026, "iso_week": 23, "category": "math.PR", "complete": true, "finalized": false, "data_through": "2026-06-07", "total_submissions": 112, "fetched": 112, "generated_at": "2026-06-09T13:18:09Z", "entries": [{"id": "2606.01627v1", "title": "The geometry of the giant component of random geometric graphs", "abstract": "Consider a random geometric graph $G_M(n;r)$ whose vertex set consists of $n$ points chosen independently and uniformly from a Riemannian manifold $M$, with edges joining pairs of vertices whose distance in the metric $d_M$ is at most $r$. Let $Δ$ denote the expected average degree of the graph. As is the case for Erdős-Rényi graphs, there is a critical value $Δ_c$, depending only on the dimension of $M$, such that if $Δ> Δ_c$ then $G_M(n;r)$ has a giant component. We show that whenever $Δ> Δ_c$, the giant component of $G_M(n;r)$, equipped with the graph distance, converges to the underlying manifold $M$ in the Gromov-Hausdorff distance after rescaling by an appropriate deterministic factor. Our result holds for $Δ$ depending on $n$ as well, provided $Δ= o(n)$ and $Δ\\geq Δ_c + \\varepsilon$ for any fixed $\\varepsilon > 0$. As a consequence, we show that for any pair of non-isometric compact Riemannian manifolds $M_1$ and $M_2$, there is a polynomial-time algorithm that distinguishes random geometric graphs on $M_1$ and $M_2$ throughout this regime of $Δ.$ In the thermodynamic regime -- i.e.\\ when $Δ$ is constant -- our results appear to be new even in the classical cases where $M$ is a sphere or a torus. Our proof makes use of techniques from first-passage percolation which allow us to understand the long-range behavior of the graph distance on small, approximately Euclidean patches of $M$, together with global arguments that glue these local estimates into a global description.", "authors": ["Karoline Dubin", "Christian Gorski", "Marcus Michelen"], "published": "2026-06-01T03:24:53Z", "updated": "2026-06-01T03:24:53Z", "primary_category": "math.PR", "categories": ["math.PR", "math.CO"], "abs_url": "https://arxiv.org/abs/2606.01627v1", "pdf_url": "https://arxiv.org/pdf/2606.01627v1", "score": 19, "matched_keywords": ["erdos", "giant component", "percolation", "random geometric graph", "renyi"], "coauthors": [], "bucket": "high"}, {"id": "2606.03442v1", "title": "Stein's method in network analysis", "abstract": "The paper consists of a brief survey of the use of Stein's method in network analysis. Topics covered include normal and Poisson approximation of graph--based statistics, approximating an exponential random graph by a Bernoulli model, and comparison of different random geometric graph models.", "authors": ["A. D. Barbour", "Adrian Fischer", "Gesine Reinert"], "published": "2026-06-02T10:26:45Z", "updated": "2026-06-02T10:26:45Z", "primary_category": "math.PR", "categories": ["math.PR"], "abs_url": "https://arxiv.org/abs/2606.03442v1", "pdf_url": "https://arxiv.org/pdf/2606.03442v1", "score": 9, "matched_keywords": ["random geometric graph", "random graph"], "coauthors": [], "bucket": "high"}, {"id": "2606.01944v1", "title": "Propagation of Chaos for Mean-field Mean Reflected Backward Stochastic Differential Equations", "abstract": "In this paper, we establish a propagation of chaos result for mean-field mean reflected backward stochastic differential equations (BSDEs), where both the generator and constraint depend on the distribution of the solution. When the generator does not rely on $z$, under mild Lipschitz and integrability conditions, we prove existence and uniqueness of the solution to the interacting particle system for general reflections. We are able to consider the case where the generator depends on $z$ when the reflection is linear. In both cases, we obtain the convergence rate of solution to the interacting particle system towards the solution to the mean-field mean reflected BSDEs.", "authors": ["Hanwu Li"], "published": "2026-06-01T09:07:30Z", "updated": "2026-06-01T09:07:30Z", "primary_category": "math.PR", "categories": ["math.PR"], "abs_url": "https://arxiv.org/abs/2606.01944v1", "pdf_url": "https://arxiv.org/pdf/2606.01944v1", "score": 7, "matched_keywords": ["interacting particle system", "particle system"], "coauthors": [], "bucket": "high"}, {"id": "2606.02036v1", "title": "Self-intersection local times for Volterra Gaussian processes in stochastic flows with interaction", "abstract": "In this paper, we study self-intersection local times for a stochastic process $x(u(\\cdot),t)$, where $u$ is a Gaussian process of the form $u(t)=\\int^t_0k(t,s)\\mathrm{d}{w(s)}$, $k$ is a deterministic kernel of the Volterra type, $w$ is a Wiener process, and $x$ is a solution to the \\emph{equation with interaction}. Equations with interaction are a class of interacting particle system described by stochastic differential equations whose coefficients depend on a random measure (initial distribution of particles) transformed by the flow of solutions. Considering the occupation measure of $u$ as the initial condition for the equation with interaction allows us to define a stochastic flow with interaction driven by self-intersection local times of the process $u$. The study of such stochastic differential equations whose coefficients carry information about the geometric properties of curves is new. They previously appeared only for deterministic differential equations and smooth curves, where the geometric characteristics typically considered are length, curvature, and so on. In this paper, we prove the existence of multiple self-intersection local times for the process $x(u(\\cdot),t)$ and establish a ``change of variable formula\" that allows us to describe self-intersection local times for the process $x(u(\\cdot),t)$ in terms of the weighted self-intersection local times for the process $u.$ We describe the corresponding asymptotics of the self-intersection local times for $x(u(\\cdot),t)$ for large $t$. Moreover, the existence of weighted self-intersection local times is established for a large class of unbounded weights, which is of independent interest.", "authors": ["Olga Izyumtseva", "Wasiur R. KhudaBukhsh"], "published": "2026-06-01T10:25:28Z", "updated": "2026-06-01T10:25:28Z", "primary_category": "math.PR", "categories": ["math.PR", "math.DS", "math.FA"], "abs_url": "https://arxiv.org/abs/2606.02036v1", "pdf_url": "https://arxiv.org/pdf/2606.02036v1", "score": 7, "matched_keywords": ["interacting particle system", "particle system"], "coauthors": [], "bucket": "high"}, {"id": "2606.01881v1", "title": "Can the root cluster remain largest forever in random recursive tree percolation?", "abstract": "We consider Bernoulli bond percolation with fixed retention parameter $p$ on the random recursive tree, coupled through the natural growth process. We prove that the root cluster has a strictly positive probability of remaining a largest cluster at every time. Equivalently, in the associated Simon-type Chinese restaurant process, the first table has a positive probability of remaining a largest table forever. We further show that two associated quantities, the limit as $n\\to\\infty$ of the probability that the root cluster is a largest cluster at time $n$ and the probability that it remains a largest cluster for all times, are strictly increasing and continuous functions of $p$ on $(0,1]$, and both tend to zero as $p\\downarrow0$.", "authors": ["Yushu Zheng"], "published": "2026-06-01T08:27:52Z", "updated": "2026-06-01T08:27:52Z", "primary_category": "math.PR", "categories": ["math.PR"], "abs_url": "https://arxiv.org/abs/2606.01881v1", "pdf_url": "https://arxiv.org/pdf/2606.01881v1", "score": 4, "matched_keywords": ["percolation"], "coauthors": [], "bucket": "medium"}, {"id": "2606.02340v1", "title": "Transitivity in Inhomogeneous Random Tournaments", "abstract": "Paired-comparison data are naturally represented by tournaments, where transitivity corresponds to the existence of a global ranking consistent with all pairwise outcomes. Accordingly, the classical Kendall-Smith coefficient of consistency measures deviations from transitivity in a tournament by counting the number of circular triads (directed $3$-cycles). In this paper, we characterize the fluctuations of the number of circular triads in inhomogeneous random tournaments and develop an inferential framework for the consistency coefficient. Specifically, we consider the $W$-random tournament model, where the comparison probabilities are determined by a tournamenton $W$, the analogue of a graphon in the tournament setting. We show that, for a $W$-random tournament on $n$ vertices, the number of circular triads exhibits three different fluctuation regimes, determined by suitable notions of regularity and uniformity of $W$. We further develop a novel tournamenton multiplier bootstrap that consistently approximates the limiting distribution of the circular-triad count in the relevant asymptotic regime. Combining this with procedures for testing regularity and uniformity, we design an algorithm for constructing confidence intervals for the consistency coefficient that is asymptotically valid for all tournamentons. We also obtain structural characterizations of tournamentons for which the limiting distribution of the number of circular triads exhibits specific degeneracies. These results can also be viewed through the lens of tournament quasirandomness and may be of independent interest.", "authors": ["Sayak Chatterjee", "Bhaswar B. Bhattacharya"], "published": "2026-06-01T14:48:19Z", "updated": "2026-06-01T14:48:19Z", "primary_category": "math.PR", "categories": ["math.PR", "math.CO", "math.ST"], "abs_url": "https://arxiv.org/abs/2606.02340v1", "pdf_url": "https://arxiv.org/pdf/2606.02340v1", "score": 4, "matched_keywords": ["inhomogeneous"], "coauthors": [], "bucket": "medium"}, {"id": "2606.02786v1", "title": "Non-local SDEs, critical drifts and local blow-ups", "abstract": "The paper is concerned with $α$-stable SDEs with singular time-inhomogeneous general drift. Our drifts satisfy a condition that is close to the minimal possible scaling-invariance and can introduce local blow-ups of the type arising in some particle systems with strong attracting interactions.", "authors": ["Damir Kinzebulatov", "Chengjun Yue"], "published": "2026-06-01T18:50:43Z", "updated": "2026-06-01T18:50:43Z", "primary_category": "math.PR", "categories": ["math.PR", "math.AP", "math.FA"], "abs_url": "https://arxiv.org/abs/2606.02786v1", "pdf_url": "https://arxiv.org/pdf/2606.02786v1", "score": 4, "matched_keywords": ["inhomogeneous"], "coauthors": [], "bucket": "medium"}, {"id": "2606.02856v1", "title": "Geometric Routing in Geometric Inhomogeneous Random Graphs", "abstract": "We present the first rigorous analysis of decentralized geometric routing in Geometric Inhomogeneous Random Graphs (GIRGs), a weight-agnostic variant of the greedy routing protocol. While greedy routing in GIRGs is known to explain the algorithmic small-world phenomenon by finding ultra-short paths of length $Θ(\\log \\log n)$, it assumes additional knowledge of vertex weights beyond geometry, an assumption that is often restrictive or unavailable. We investigate whether the underlying geometry alone is sufficient for efficient navigation. We prove that for power-law weight exponent $τ\\in (2,3)$ and geometric decay parameter $α> τ- 1$, geometric routing succeeds with constant probability and finds ultra-short paths of length $Θ(\\log \\log n)$, matching the optimal asymptotic guarantees for greedy routing. Our analysis further reveals that, upon success, both protocols follow a similar two-phase trajectory, consisting of a rapid ascent to the heavy vertices, followed by efficient navigation to the target. These results demonstrate that, in the appropriate regime, the network's geometry alone implicitly guides the path to the target through its high-weight core.", "authors": ["Yu-Cheng Chiu", "Marc Kaufmann", "Kostas Lakis", "Ulysse Schaller"], "published": "2026-06-01T20:19:25Z", "updated": "2026-06-01T20:19:25Z", "primary_category": "math.PR", "categories": ["math.PR", "cs.SI", "math.CO"], "abs_url": "https://arxiv.org/abs/2606.02856v1", "pdf_url": "https://arxiv.org/pdf/2606.02856v1", "score": 4, "matched_keywords": ["inhomogeneous"], "coauthors": [], "bucket": "medium"}, {"id": "2606.03006v1", "title": "Logarithmic regularity of spectral measures on infinite graphs", "abstract": "We study the regularity of spectral measures of self-adjoint operators on infinite weighted graphs in the unimodular setting. This framework encompasses operators in the group algebra of a finitely generated group, random operators whose distribution is quasi-invariant under a group action, and Benjamini--Schramm limits of operators on finite graphs. Under a natural geometric condition on the underlying graph, we prove that the expected spectral measure satisfies a logarithmic Hölder regularity estimate. The proof relies on a strengthened version of the monotone labelling method previously introduced with Sen and Virág to control the pure point part of the spectal measure. Applications include operators in group algebras of indicable groups, Anderson-type models with arbitrary compactly supported potentials on Cayley graphs, anisotropic percolation operators, and operators on quasi-transitive graphs. In particular, our results extend the classical Craig--Simon theorem beyond the Euclidean lattice.", "authors": ["Charles Bordenave"], "published": "2026-06-02T01:26:01Z", "updated": "2026-06-02T01:26:01Z", "primary_category": "math-ph", "categories": ["math-ph", "math.GR", "math.PR"], "abs_url": "https://arxiv.org/abs/2606.03006v1", "pdf_url": "https://arxiv.org/pdf/2606.03006v1", "score": 4, "matched_keywords": ["percolation"], "coauthors": [], "bucket": "medium"}, {"id": "2606.05039v1", "title": "Geometric approximation for the number of returns of a transient Markov chain to its origin", "abstract": "Given a discrete-time, transient Markov chain, we establish explicit total variation error bounds in the approximation of the number of visits to its starting state within the first $n$ time steps by a geometric distribution. Our error bounds are expressed in terms of the heat kernel of the Markov chain. As applications, we consider Galton--Watson processes with a geometric offspring distribution, and random walks on the one- and three-dimensional integer lattices, regular trees, supercritical percolation clusters, and groups with polynomial growth.", "authors": ["Fraser Daly", "Seva Shneer"], "published": "2026-06-03T16:03:10Z", "updated": "2026-06-03T16:03:10Z", "primary_category": "math.PR", "categories": ["math.PR"], "abs_url": "https://arxiv.org/abs/2606.05039v1", "pdf_url": "https://arxiv.org/pdf/2606.05039v1", "score": 4, "matched_keywords": ["percolation"], "coauthors": [], "bucket": "medium"}, {"id": "2606.07065v1", "title": "Ising Models on Inhomogeneous Random Graphs: Inference, Local Asymptotic Minimaxity, and Limit of Experiments", "abstract": "In this paper, we develop an inferential framework with sharp asymptotic optimality guarantees for Ising models on inhomogeneous random graphs in the subcritical parameter regime. We begin by characterizing the asymptotic distribution of the maximum likelihood (ML) estimate of the natural parameter, based on a single sample from the underlying model, covering both sparse and dense network regimes. Next, to overcome the computational intractability of the ML method, we propose a simple closed-form estimate obtained from a one-step approximation to the likelihood equation. We show that this estimate attains the same asymptotic distribution and variance as the ML estimate, thereby yielding a computationally efficient and asymptotically valid confidence interval for the natural parameter. We complement these inferential results by establishing a Hájek--Le Cam-type local asymptotic minimax theorem, showing that the proposed estimate achieves the smallest possible asymptotic maximum risk, both in rate and in leading constant, over shrinking neighborhoods of the true parameter. We also derive the corresponding limit of experiments. To the best of our knowledge, these are among the first sharp asymptotic optimality results for network-dependent data. Finally, we study goodness-of-fit testing for the natural parameter, deriving the local power of the likelihood ratio test and minimax detection rates. Our analysis relies on new fluctuation results for the sufficient statistic (Hamiltonian) and for the random partition function of Ising models on inhomogeneous random graphs, which are of independent interest.", "authors": ["Somabha Mukherjee", "Sanchayan Bhowal", "Anirban Chatterjee", "Bhaswar B. Bhattacharya"], "published": "2026-06-05T09:05:29Z", "updated": "2026-06-05T09:05:29Z", "primary_category": "math.ST", "categories": ["math.ST", "math.PR", "stat.ME"], "abs_url": "https://arxiv.org/abs/2606.07065v1", "pdf_url": "https://arxiv.org/pdf/2606.07065v1", "score": 4, "matched_keywords": ["inhomogeneous"], "coauthors": [], "bucket": "medium"}, {"id": "2606.08884v1", "title": "A Poincaré Inequality and Exponential Decay for the Elephant Random Walk", "abstract": "We study the long-time behaviour of a coninuous time one-dimensional elephant random walk with an absorbing boundary. By analyzing the associated evolution equation, we identify a proper limiting operator and establish a Poincaré inequality with spectral gap of order $N^{-2}$. As a consequence, we obtain matching exponential upper and lower bounds for the survival probability, showing that it decays at rate $e^{-ct/N^2}$. The proof relies on a decomposition of the generator into a limiting operator and a time-dependent perturbation, together with spectral estimates.", "authors": ["Cristian Favio Coletti", "Rafael de Mattos Grisi", "Ioannis Papageorgiou"], "published": "2026-06-07T23:56:13Z", "updated": "2026-06-07T23:56:13Z", "primary_category": "math.PR", "categories": ["math.PR"], "abs_url": "https://arxiv.org/abs/2606.08884v1", "pdf_url": "https://arxiv.org/pdf/2606.08884v1", "score": 4, "matched_keywords": ["random walk", "survival"], "coauthors": [], "bucket": "medium"}, {"id": "2606.01866v1", "title": "Phase Transition of a Semiflexible Membrane in Two Dimensions", "abstract": "We study a two-dimensional semiflexible membrane model whose formal Hamiltonian is given by $H[φ]=\\sum_x \\bigl(\\|\\nabla φ_x\\|^2 +N^λ|Δφ_x|^2\\bigr)$, interpolating between the discrete Gaussian free field (DGFF) and the membrane model (MM). We analyze its finite-volume covariance in the bulk as $N\\to\\infty$, and identify distinct regimes depending on the parameter $λ$. For $λ<0$, the covariance of the model agrees with that of the DGFF up to a negligible error, while for $λ>2$, it agrees with the rescaled MM covariance up to a negligible error. In the intermediate regime $λ\\in[0,2]$, we identify a different crossover behavior: in the microscopic range $\\|x-y\\|\\ll N^{λ/2}$, the leading asymptotics no longer resolve the precise distance between the two points. In this microscopic regime, we further determine the leading logarithmic coefficient of the bulk covariance. These results provide a unified description of the crossover from gradient-dominated to curvature-dominated behavior in this class of models.", "authors": ["Jingu Hwang"], "published": "2026-06-01T08:15:28Z", "updated": "2026-06-01T08:15:28Z", "primary_category": "math.PR", "categories": ["math.PR"], "abs_url": "https://arxiv.org/abs/2606.01866v1", "pdf_url": "https://arxiv.org/pdf/2606.01866v1", "score": 3, "matched_keywords": ["phase transition"], "coauthors": [], "bucket": "medium"}, {"id": "2606.05140v1", "title": "Phase transitions for the noisy transformer model in arbitrary dimension", "abstract": "We study the McKean--Vlasov free energy on the unit sphere associated with the unnormalized self-attention (USA) model for noisy transformer dynamics. We prove a sharp global-minimizer dichotomy in every dimension $d\\ge2$. There is a unique $β_*^{(d)}>0$ such that \\begin{equation*} \\frac{I_{d/2+1}(β_*^{(d)})}{I_{d/2}(β_*^{(d)})}=\\frac1d, \\end{equation*} where $I_ν$ is the modified Bessel function of the first kind. For $0<β\\le β_*^{(d)}$, the uniform density remains the unique global minimizer up to the linear-stability threshold \\begin{equation*} K_\\#^{(d)}(β)=\\frac{β^{d/2}}{2^{d/2}Γ(d/2)I_{d/2}(β)}, \\end{equation*} and the phase transition is continuous. For $β>β_*^{(d)}$, the uniform density is not globally minimizing at $K_\\#^{(d)}(β)$, so the critical coupling satisfies $K_c<K_\\#^{(d)}(β)$ and the transition is discontinuous. This result generalizes the authors' recent $d=2$ work arXiv:2604.16288 to arbitrary dimension. The proof uses the sharp Beckner--Onofri/logarithmic Hardy-Littlewood-Sobolev (HLS) inequality on the sphere, together with a Funk--Hecke/Bessel coefficient computation and a degree-two quartic obstruction.", "authors": ["Kyunghoo Mun", "Matthew Rosenzweig"], "published": "2026-06-03T17:49:43Z", "updated": "2026-06-03T17:49:43Z", "primary_category": "math.AP", "categories": ["math.AP", "math-ph", "math.PR", "stat.ML"], "abs_url": "https://arxiv.org/abs/2606.05140v1", "pdf_url": "https://arxiv.org/pdf/2606.05140v1", "score": 3, "matched_keywords": ["phase transition"], "coauthors": [], "bucket": "medium"}, {"id": "2606.07757v1", "title": "REM universality and Poisson-Dirichlet Gibbs weights for linear random energy", "abstract": "We study the Hamiltonian $H_n(h,σ)=\\sum_{i=1}^n h_i(σ_i-m), $ where $(h_i)$ are i.i.d.\\ real random variables and $(σ_i)$ are i.i.d.\\ Ising spins. We consider the energy levels obtained after an independent thinning that retains an exponential number of configurations ($e^{O(n)}$). We prove that, after an $(h_i)$-dependent centering, the resulting point process converges in distribution to a Poisson point process with exponential intensity. Thus, the energy levels asymptotically has the one of the Random Energy Model (REM). Our results extend previous ones, where REM universality for this model was established only either for energy fluctuations of order $e^{-O(n)}$ or for $e^{o(\\sqrt n)}$ randomly selected configurations. We also identify the limiting Gibbs weights, which converge to a Poisson--Dirichlet law, and the quenched free energy, which exhibits a freezing transition at $β=\\tildeλ$. The proofs are presented here in compressed form; full details are given in the companion preprint.", "authors": ["Francesco Concetti", "Simone Franchini"], "published": "2026-06-05T18:13:05Z", "updated": "2026-06-05T18:13:05Z", "primary_category": "math.PR", "categories": ["math.PR", "cond-mat.stat-mech"], "abs_url": "https://arxiv.org/abs/2606.07757v1", "pdf_url": "https://arxiv.org/pdf/2606.07757v1", "score": 3, "matched_keywords": ["point process"], "coauthors": [], "bucket": "medium"}, {"id": "2606.08304v1", "title": "Functions of Bounded Variation and Point Processes", "abstract": "We investigate the relationship between the analytical properties of functions of bounded variation and the statistical behavior of hyperuniform point processes. We establish several characterization formulas for the jump part of the gradient of a bounded variation function, extending and unifying previous results by Beretti--Gennaioli and Dávila. In particular, we provide new expressions for the $L^2$-jump of the gradient using both difference quotients and Fourier transform methods. Furthermore, we connect these analytic structures to the theory of hyperuniform point processes. By analyzing the variance of linear statistics associated with bounded variation functions, we provide asymptotic estimates that depend on the specific classification of the hyperuniformity of the point process. The results show how the regularity and jump discontinuities of a function dictate the growth rate of fluctuations in point processes. Finally, we introduce an averaged quadratic BMO-type oscillation functional over translated and rotated cube partitions, similar to the one recently studied by Ambrosio et al., and prove, using results from point process, that it converges to an explicit dimensional constant times the $L^2-$jump, giving in particular a further new characterization of the perimeter of a set.", "authors": ["J. Antezana", "M. Levi", "J. Marzo", "J. Ortega-Cerdà"], "published": "2026-06-06T19:14:58Z", "updated": "2026-06-06T19:14:58Z", "primary_category": "math.CA", "categories": ["math.CA", "math.PR"], "abs_url": "https://arxiv.org/abs/2606.08304v1", "pdf_url": "https://arxiv.org/pdf/2606.08304v1", "score": 3, "matched_keywords": ["point process"], "coauthors": [], "bucket": "medium"}, {"id": "2606.08581v1", "title": "The Pile Process on a Cycle", "abstract": "Consider a finite particle system in which, at each step, one particle from a vertex with a lower neighboring vertex moves to a neighboring vertex of minimum height. For the cycle C_n, started with n particles at one vertex and no particles elsewhere, we prove that the expected stabilization time is at most a constant multiple of n^3 The deterministic transportation lower bound is of order n^2. Simulations suggest that the true order should be near n^3. Chat GPT was used to reincarnate notes from 2007.", "authors": ["Itai Benjamini", "Eric Shellef"], "published": "2026-06-07T11:32:47Z", "updated": "2026-06-07T11:32:47Z", "primary_category": "math.PR", "categories": ["math.PR"], "abs_url": "https://arxiv.org/abs/2606.08581v1", "pdf_url": "https://arxiv.org/pdf/2606.08581v1", "score": 3, "matched_keywords": ["particle system"], "coauthors": [], "bucket": "medium"}, {"id": "2606.02847v1", "title": "Sharp Log-Sobolev Inequalities for Finite Cyclic Groups with Word-Length", "abstract": "Let $\\mathbb Z_n$ be the cyclic group equipped with the uniform probability measure $π$, and let $-A_{ψ_n}$ be the Laplacian with respect to the word length $ ψ_n(k) = \\min(k,n-k). $ We prove the sharp log-Sobolev inequality $$ \\operatorname{Ent}_π(f^2) \\le 2π\\bigl(f A_{ψ_n} f\\bigr), \\qquad f:\\mathbb Z_n \\to \\mathbb C, $$ for every $n \\ge 4$. The proof is inspired by the recent work of Frank and Ivanisvili~\\cite{FrankIvanisvili2026} on a sharp log-Sobolev inequality for nearest-neighbor simple random walk. We use their idea of cubic-majorant reduction, but replace their high-frequency estimate with a Fourier block estimate adapted to the word-length multiplier. The same result was also recently obtained by Yao~\\cite{Yao2026} using a completely different approach.", "authors": ["Xinyuan Xie", "Haonan Zhang"], "published": "2026-06-01T20:11:29Z", "updated": "2026-06-01T20:11:29Z", "primary_category": "math.CA", "categories": ["math.CA", "math.FA", "math.PR"], "abs_url": "https://arxiv.org/abs/2606.02847v1", "pdf_url": "https://arxiv.org/pdf/2606.02847v1", "score": 2, "matched_keywords": ["random walk"], "coauthors": [], "bucket": "other"}, {"id": "2606.06522v1", "title": "On the Duke--Erdős--Rödl Problem at the One-Third Threshold", "abstract": "Let $G$ be an $n$-vertex graph with $e(G)\\ge n^2/k$. We prove a self-contained internal short-cycle core theorem at the threshold $k\\le n^{1/3}$: the graph $G$ contains a subgraph $H_6$ with $Ω(n^2/k^3)$ edges in which every two distinct edges lie together on a cycle of length at most $6$ contained in $H_6$, and a subgraph $H_8$ with $Ω(n^2/k^2)$ edges in which every two distinct edges lie together on a cycle of length at most $8$ contained in $H_8$. In density notation $ρ=e(G)/n^2$, this gives internal cores of sizes $Ω(ρ^3n^2)$ and $Ω(ρ^2n^2)$ throughout the range $ρ\\ge n^{-1/3}$. The $C_{\\le6}$ conclusion above is an edge-connected statement and does not impose the adjacent-edge $C_4$ condition appearing in the strongest Duke--Erdős--Rödl formulation. We also include two complementary results clarifying this distinction. First, under the ambient-witness convention, every graph with at least $n^2/k$ edges and $k=o(n^{1/2})$ contains $Ω(n^2/k^3)$ selected edges whose pairs are witnessed by ambient cycles of length at most $6$, with adjacent pairs witnessed by ambient $C_4$'s. Second, under the standard internal strong $C_6$ convention, for every fixed $β\\in[1/3,1/2)$ there is an infinite sequence of bipartite graphs $G$ with $n\\to\\infty$ and $e(G)=Θ_β(n^{2-β})$ such that every internally strongly $C_6$-connected subgraph has only $O_β(ρ(G)^3n^2/(\\log n)^2)$ edges. The obstruction is a random cyclic shift-lift of $K_{q,q}$, together with an occupancy estimate excluding large aligned two-covers.", "authors": ["Eric Li"], "published": "2026-06-02T18:40:38Z", "updated": "2026-06-02T18:40:38Z", "primary_category": "math.CO", "categories": ["math.CO", "cs.DM", "math.PR"], "abs_url": "https://arxiv.org/abs/2606.06522v1", "pdf_url": "https://arxiv.org/pdf/2606.06522v1", "score": 2, "matched_keywords": ["erdos"], "coauthors": [], "bucket": "other"}, {"id": "2606.04131v1", "title": "Network node immunization: improving Netshield algorithm through random rooted forests", "abstract": "We are interested in the so-called multiple-node immunization problem for complex networks under attack by a viral agent. It consists in identifying and removing a set of nodes of size $k$ in a graph to maximize the impeding of virus spread. A few approaches have been proposed in the literature based on numerical and theoretical insights on how classical models for virus spread evolve on graphs. Based on the analysis of these models, the maximal eigenvalue of the adjacency matrix of the graph has become a classical measure of how resilient the network is. Thus, a clear, well-explored approach for multiple-node immunization consists of identifying a set of $k$ nodes in such a way that the reduced network, obtained by removing these nodes, has a minimal largest eigenvalue. This spectral optimization problem turns out to be a computationally hard problem for which only greedy algorithms offer good solutions at efficient computational time. Among those, the so-called Netshield algorithm represents one of the reference choices. The latter is, in fact, a clearly defined algorithm aiming at optimizing a certain sub-modular functional, called shield-value, which approximates the original optimization problem. We propose here a novel procedure, based on random walk kernels and related random spanning forests, to build a new algorithm, referred to as K-shield, which enhances Netshield searching performance at the same computational complexity. We give theoretical insights behind this novel method, which could also be used for other optimization problems, and then test it via numerical showcase experiments on various benchmarks.", "authors": ["Luca Avena", "Alexandre Gaudillière", "Irina Gurewitsch", "Adoré Randriamandroso", "Alessio Troiani"], "published": "2026-06-02T18:41:45Z", "updated": "2026-06-02T18:41:45Z", "primary_category": "cs.SI", "categories": ["cs.SI", "math.PR"], "abs_url": "https://arxiv.org/abs/2606.04131v1", "pdf_url": "https://arxiv.org/pdf/2606.04131v1", "score": 2, "matched_keywords": ["random walk"], "coauthors": [], "bucket": "other"}, {"id": "2606.04837v1", "title": "Maximal Minimal Spacing for Random Points", "abstract": "From $N+1$ random points on a line we wish to select $M+1$ points so as to maximize the minimal spacing between them. We consider an initial configuration with independent and identically distributed spacings. The problem is equivalent to optimally grouping consecutive gaps into $M$ blocks and maximizing the smallest block sum. For general gap distributions, and for all $M\\leq N$, we derive exact distributional identities for the optimal spacing and obtain its asymptotic behavior. The problem admits a reformulation in terms of a threshold-resetting random walk. The walk advances by successive random increments and is reset to the origin upon exceeding a fixed threshold. The probability that the optimal spacing exceeds a given value coincides with the probability that the walk completes at least $M$ reset cycles within $N$ steps. This yields an exact representation in terms of first-passage functionals of the walk. The same mapping suggests a numerical scheme for the max-min spacing problem in the regime of large $N$ and $M$, whose accuracy is tested against the exact results obtained here.", "authors": ["Fabio Deelan Cunden", "Noemi Cuppone", "Giovanni Gramegna", "Pierpaolo Vivo"], "published": "2026-06-03T13:07:41Z", "updated": "2026-06-03T13:07:41Z", "primary_category": "math-ph", "categories": ["math-ph", "cond-mat.stat-mech", "math.PR"], "abs_url": "https://arxiv.org/abs/2606.04837v1", "pdf_url": "https://arxiv.org/pdf/2606.04837v1", "score": 2, "matched_keywords": ["random walk"], "coauthors": [], "bucket": "other"}, {"id": "2606.05830v1", "title": "Biased Random Walk on $\\mathbb Z_+$ with Traps of Linearly Increasing Depth", "abstract": "We study a $λ$-biased random walk $(X_n)_{n\\ge0}$ on the deterministic infinite rooted tree $\\mathcal{T}=\\{(i,j): i\\ge0,\\,0\\le j\\le i\\}$, whose backbone is $\\{(i,0):i\\ge0\\}$ and, for each $i\\ge1$, the segment $\\{(i,j):1\\le j\\le i\\}$ forms a trap attached to $(i,0)$. The trapping effect induces long sojourns, yielding asymptotics markedly different from simple random walks. The walk is recurrent for $λ\\ge1$ and transient for $0<λ<1$. In the transient regime it is sub-ballistic: its distance from the root grows logarithmically, with \\[ \\liminf_{n\\to\\infty}\\frac{|X_n|}{\\log n}=\\frac{1}{\\log(1/λ)},\\quad \\limsup_{n\\to\\infty}\\frac{|X_n|}{\\log n}=\\frac{2}{\\log(1/λ)},\\quad\\text{a.s.}. \\] A contrast between spatial and temporal regeneration emerges. Let $C(n)$ be the number of cutpoints among the first $n$ backbone vertices and $M(N)$ the number of cut times up to time $N$. Then \\[ \\lim_{n\\to\\infty}\\frac{C(n)}{n}= 1-λ,\\qquad \\lim_{N\\to\\infty}\\frac{M(N)}{\\log N}=\\frac{1-λ}{\\log(1/λ)},\\quad\\text{a.s.}, \\] so cutpoints have positive linear density while cut times grow only logarithmically.", "authors": ["Hua-Ming Wang", "Ning Wang"], "published": "2026-06-04T08:08:36Z", "updated": "2026-06-04T08:08:36Z", "primary_category": "math.PR", "categories": ["math.PR"], "abs_url": "https://arxiv.org/abs/2606.05830v1", "pdf_url": "https://arxiv.org/pdf/2606.05830v1", "score": 2, "matched_keywords": ["random walk"], "coauthors": [], "bucket": "other"}, {"id": "2606.07194v1", "title": "Survival Probability of Markov Linear Reccurence Sequence in a Random Environment: Subcritical Case", "abstract": "The Markov linear recurrence sequence in a random environment (MRSRE) is a particular case of Markov chain on non-negative integers. It is a natural generalization of several models with branching. We consider MRSRE with absorption at zero and study the survival time. We introduce a classification of subcritical MRSRE corresponding to that of branching process in a random environment. We show that general R-positivity theory can be applied to this model in a strongly subcritical case and prove the analogues of the Kolmogorov theorem and the Yaglom theorem. In other words, we describe the asymptotic behavior of the survival probability over a long time and the conditional distribution of the sequence, conditioned on the survival event. The results are applied to particular branching models.", "authors": ["Alexander Shklyaev"], "published": "2026-06-05T12:01:02Z", "updated": "2026-06-05T12:01:02Z", "primary_category": "math.PR", "categories": ["math.PR"], "abs_url": "https://arxiv.org/abs/2606.07194v1", "pdf_url": "https://arxiv.org/pdf/2606.07194v1", "score": 2, "matched_keywords": ["survival"], "coauthors": [], "bucket": "other"}, {"id": "2606.07480v1", "title": "Erdős-Kac theorems for discriminants of number fields", "abstract": "The classical Erdős-Kac theorem gives a central limit theorem for the number of prime divisors of a random integer. We prove an analog for the number of ramified primes in a random $G$-extension of a number field when $G$ is abelian. This builds on previous work of Lemke Oliver and Thorne in the cases $G = S_d$ ($2 \\le d \\le 5$), and provides the first examples where local ramification events at distinct primes are not independent. We develop probability results that can be used \"out of the box\" to prove Erdős-Kac theorems for sequences of ideals in a number field, subject to Tauberian hypotheses involving finite sums of Euler products.", "authors": ["Jack B. Miller"], "published": "2026-06-05T17:34:54Z", "updated": "2026-06-05T17:34:54Z", "primary_category": "math.NT", "categories": ["math.NT", "math.PR"], "abs_url": "https://arxiv.org/abs/2606.07480v1", "pdf_url": "https://arxiv.org/pdf/2606.07480v1", "score": 2, "matched_keywords": ["erdos"], "coauthors": [], "bucket": "other"}, {"id": "2606.08115v1", "title": "Non-exctinction probability for two branching processes in a joint random environment", "abstract": "The paper introduces the model of a pair of branching processes $\\{\\boldsymbol{Z_n} = \\left(Z_n^{(1)}, Z_n^{(2)}\\right), \\; n \\in \\mathbb{N}_0\\}$ in a joint random environment. If the environment is fixed then the sequences $\\{Z_n^{(1)}, \\; n \\in \\mathbb{N}_0\\}$ and $\\{Z_n^{(2)},\\; n \\in \\mathbb{N}_0\\}$ are independent branching processes in a varying environment. This model is a particular case of a more general model of a multitype branching process in a random environment. We establish the asymptotic relation ${\\bf{P}}\\left(Z_n^{(1)} > 0, Z_n ^{(2)}>0 \\right) \\sim C n^{-a}$ as $n \\to \\infty$, where the parameter $a$ depends only on the correlation coefficient $ρ$ of an increment of a two-dimensional associated random walk.", "authors": ["Dmitrii Arapov"], "published": "2026-06-06T11:36:15Z", "updated": "2026-06-06T11:36:15Z", "primary_category": "math.PR", "categories": ["math.PR"], "abs_url": "https://arxiv.org/abs/2606.08115v1", "pdf_url": "https://arxiv.org/pdf/2606.08115v1", "score": 2, "matched_keywords": ["random walk"], "coauthors": [], "bucket": "other"}, {"id": "2606.08216v1", "title": "Erdős Problem 684 at Density One: Small-prime Parts of Binomial Coefficients and Gaussian Fluctuations", "abstract": "For $0\\leq k\\leq n$, let $u(n,k)$ be the largest divisor of $\\binom nk$ whose prime factors are at most $k$. Erdős Problem #684 concerns the special threshold $u(n,k)>n^2$ and asks how early this small-prime part can be forced to become large. We prove the density-one analogue for every fixed power threshold. If $f_c(n)$ is the least $k$ for which $u(n,k)>n^c$, then, for each fixed $c>0$, \\[ f_c(n)=\\left(\\frac{c}{1-γ}+o(1)\\right)\\log n \\] for almost all positive integers $n$. In particular, \\[ f_2(n)=\\left(\\frac{2}{1-γ}+o(1)\\right)\\log n =(4.730544237\\ldots+o(1))\\log n \\] for the Erdős #684 threshold. This is a normal-order theorem, not a pointwise resolution of the corresponding worst-case problem. The constant $1-γ$ is arithmetic. Kummer's theorem rewrites $\\log u(n,k)$ as a sum of carry indicators, and complete-residue averaging gives \\[ m(k)=k\\sum_{p\\leq k}\\frac{\\log p}{p-1}-\\log k!=(1-γ)k+o(k). \\] The cancellation in this formula moves the typical crossing from the naive scale $c\\log n$ to $c(1-γ)^{-1}\\log n$. We prove the required concentration uniformly for every $k\\leq A\\log X$ on one dyadic interval, after discarding a zero-density exceptional set caused by large powers of small primes dividing one of the nearby integers $n,n-1,\\ldots$. We also prove Gaussian fluctuations in the logarithmic range. If $k=k(X)\\to\\infty$, $k\\leq A\\log X$, and $n$ is uniform in $[X,2X)\\cap\\mathbb Z$, then \\[ \\frac{\\log u(n,k)-m(k)}{\\sqrt{V(k)}}\\Rightarrow \\mathcal N(0,1), \\qquad V(k)\\sim (2-\\log(2π))k\\log k. \\] Higher prime powers are needed for the mean, but after centering their aggregate is $L^2$-negligible on the Gaussian scale; the variance comes only from the prime levels.", "authors": ["Eric Li"], "published": "2026-06-06T15:10:08Z", "updated": "2026-06-06T15:10:08Z", "primary_category": "math.NT", "categories": ["math.NT", "math.PR"], "abs_url": "https://arxiv.org/abs/2606.08216v1", "pdf_url": "https://arxiv.org/pdf/2606.08216v1", "score": 2, "matched_keywords": ["erdos"], "coauthors": [], "bucket": "other"}, {"id": "2606.01664v1", "title": "Brown measure convergence for the spectrum of polynomials in Ginibre matrices", "abstract": "Fix a multivariate polynomial $\\mathfrak{p}$ in $n$ non-commuting variables of arbitrary degree, and consider $n$ independent $N\\times N$ complex Ginibre matrices $X_1^N,\\cdots,X_n^N$. We prove that the empirical spectral distribution of $P^N=\\mathfrak{p}(X_1^N,\\cdots,X_n^N)$ converges as $N$ tends to infinity to the so-called Brown measure of $\\mathfrak{p}$ evaluated at free circular variables. For polynomials of degree at most 2, the convergence was proven by Cook, Guionnet, and Husson \\cite{cook2022spectrum}, and we prove that the convergence in fact holds for polynomials $\\mathfrak{p}$ of any degree. The main step in the proof is a least singular value lower bound for $P^N-z$ for almost all complex shifts $z$, and we prove this via a least singular value lower bound for a wide class of tensorized Ginibre matrices of finite type with a deterministic shift, which is of independent interest. We further show that the Brown measure convergence holds beyond Gaussians: the same convergence holds when the entry law has mean 0, variance 1, bounded density on $\\mathbb{C}$ and finite moments of all orders.", "authors": ["Yi Han"], "published": "2026-06-01T04:18:29Z", "updated": "2026-06-01T04:18:29Z", "primary_category": "math.PR", "categories": ["math.PR"], "abs_url": "https://arxiv.org/abs/2606.01664v1", "pdf_url": "https://arxiv.org/pdf/2606.01664v1", "score": 0, "matched_keywords": [], "coauthors": [], "bucket": "other"}, {"id": "2606.01683v1", "title": "Singular-value gap of nonreversible Markov processes", "abstract": "We consider a generalization of the spectral gap of reversible Markov generators to nonreversible processes, following the recent work arXiv:2310.10876 on nonreversible finite-state Markov chains. Extending Chatterjee's observations, we find that this spectral quantity that we call the \\textit{singular-value gap} characterizes the convergence of empirical averages, providing upper and lower bounds for finite-time variance uniformly over $L^2$-functions. A key observation is that when the singular-value gap is positive, the generator is invertible on the $L^2$-orthogonal complement of constant functions. In particular, the Poisson equation $-Lf = g$ can be solved, which enables our proof and connects our results to asymptotic variance and associated central limit theorems. We also compare the singular-value gap with the spectral gap of the reversibilized process, the mixing time in total-variation distance, and the Cheeger constant. Several examples are provided throughout the text. Among other potential applications of the singular-value gap, these examples illustrate that a positive singular-value gap can help with variance reduction for observable classes in MCMC sampling, uncover slow-mixing mechanisms, and certify convergence of empirical averages for diffusion operators with complicated spectrum.", "authors": ["Ruochuan Xu"], "published": "2026-06-01T04:49:03Z", "updated": "2026-06-01T04:49:03Z", "primary_category": "math.PR", "categories": ["math.PR", "math.SP"], "abs_url": "https://arxiv.org/abs/2606.01683v1", "pdf_url": "https://arxiv.org/pdf/2606.01683v1", "score": 0, "matched_keywords": [], "coauthors": [], "bucket": "other"}, {"id": "2606.01742v1", "title": "Large deviation principles for SPDEs with locally Lipschitz coefficients", "abstract": "Consider the stochastic partial differential equation, \\begin{align*} \\partial_t u^{\\varepsilon}(t\\,,x) = \\frac{1}{2} \\partial^2_x u^{\\varepsilon}(t\\,,x) + b(t\\,,u^{\\varepsilon}(t\\,,x)) + \\sqrt{\\varepsilon}σ(t\\,,u^{\\varepsilon}(t\\,,x)) \\dot{W}(t\\,,x), \\end{align*} where $(t\\,,x)\\in(0\\,,\\infty)\\times\\mathbb{R}$, and $\\dot{W}$ denotes space-time white noise. Foondun, Khoshnevisan, and Nualart \\cite{FKN24} showed that this stochastic partial differential equation is well-posed under the assumptions that the initial condition $u(0)$ is bounded and measurable, while $b$ and $σ$ are locally Lipschitz continuous functions with at most linear growth. A Freidlin-Wentzell large deviation principle for the stochastic partial differential equation is established by a weak convergence approach in this paper.", "authors": ["Beibei Zhang", "Bin Qian"], "published": "2026-06-01T06:05:44Z", "updated": "2026-06-01T06:05:44Z", "primary_category": "math.PR", "categories": ["math.PR"], "abs_url": "https://arxiv.org/abs/2606.01742v1", "pdf_url": "https://arxiv.org/pdf/2606.01742v1", "score": 0, "matched_keywords": [], "coauthors": [], "bucket": "other"}, {"id": "2606.01832v1", "title": "MA(1) processes with uniform innovations conditioned to stay positive in the non-expanding regime", "abstract": "We study an MA(1)-process with uniform innovations conditioned to stay positive. Representing the model as a Markov chain, we prove the existence of the limiting finite-dimensional distributions under this conditioning and identify the limiting process explicitly as a Doob $h$-transform. In the non-expanding case, i.e. when the coupling parameter $θ$ satisfies $θ\\in[-1,1)$, we compute the relevant generating functions, extract sharp persistence asymptotics, and give explicit formulas for the eigenfunction $h$ and the persistence exponent. The resulting transition kernel of the limiting process is therefore fully explicit and displays a phase-dependent structure in the parameters. This provides a rare solvable example of a Markov chain on a continuous state space conditioned on persistence.", "authors": ["Frank Aurzada", "Virginia Worf"], "published": "2026-06-01T07:46:11Z", "updated": "2026-06-01T07:46:11Z", "primary_category": "math.PR", "categories": ["math.PR"], "abs_url": "https://arxiv.org/abs/2606.01832v1", "pdf_url": "https://arxiv.org/pdf/2606.01832v1", "score": 0, "matched_keywords": [], "coauthors": [], "bucket": "other"}, {"id": "2606.01937v1", "title": "Stationary fluctuations for an exclusion process with mass and energy conservation", "abstract": "We introduce a novel exclusion process with two conservation laws, mass and energy, designed to mimic the essential features of continuous systems like interacting oscillators within the framework of interacting particle systems. This distinguishes our model from conventional multi-species processes where only particle numbers are conserved. As a basis for our fluctuation analysis, we first show that applying nonlinear fluctuating hydrodynamics (NFH) to this model reveals a wide variety of universality classes depending on the parameter choices. The main objective of this work is to study the stationary fluctuations of these conserved quantities. For a suitable choice of parameters, we rigorously show that the fluctuation fields converge to uncoupled stochastic Burgers equations (SBE) in the scaling limit. The proof relies on the second-order Boltzmann-Gibbs principle that we establish for this model, along with the spectral gap estimate and the equivalence of ensembles. Of independent interest is our general proof of the diagonalizability of the Jacobian matrix for the macroscopic current with distinct real eigenvalues. While this property is often taken as given in the physics literature, we establish it rigorously for multi-component systems even when the eigenvectors cannot be explicitly computed, offering a firm mathematical foundation for a broad class of models.", "authors": ["Hugo Da Cunha", "Makiko Sasada"], "published": "2026-06-01T09:02:39Z", "updated": "2026-06-01T09:02:39Z", "primary_category": "math.PR", "categories": ["math.PR", "math-ph"], "abs_url": "https://arxiv.org/abs/2606.01937v1", "pdf_url": "https://arxiv.org/pdf/2606.01937v1", "score": 0, "matched_keywords": [], "coauthors": [], "bucket": "other"}, {"id": "2606.01963v1", "title": "Improved Amenability Bounds for Local Coordination Games", "abstract": "We study local pure coordination games on finite social networks, continuing the framework of Hutchcroft, Rospuskova, and Tamuz. They showed that low inefficiency in local coordination forces the underlying graph to be amenable, with a square-root loss in the amenability parameter. We improve this loss in the binary unbiased setting. Using Shapley values of a mutual-information game associated with the players' local outputs, we prove that if the average disagreement is at most $\\varepsilon$, then the graph is $(O(\\varepsilon\\log(1/\\varepsilon)),r)$-amenable. This gives a sharper quantitative converse between local coordination and graph amenability.", "authors": ["Ron Peretz", "Dean Kraizberg"], "published": "2026-06-01T09:26:50Z", "updated": "2026-06-01T09:26:50Z", "primary_category": "cs.GT", "categories": ["cs.GT", "cs.IT", "math.PR"], "abs_url": "https://arxiv.org/abs/2606.01963v1", "pdf_url": "https://arxiv.org/pdf/2606.01963v1", "score": 0, "matched_keywords": [], "coauthors": [], "bucket": "other"}, {"id": "2606.01986v1", "title": "Generalised eigenvector expansion of infinite Toeplitz matrices with absolutely/completely monotone entries", "abstract": "We study the spectral theory of infinite Toeplitz matrices $T = (a_{k - l})$ under the assumption that $(a_k)$ and $(a_{-k})$ are completely monotone sequences. We derive expressions for generalised eigenvectors and prove a generalised eigenvector expansion of $T$. Even if the matrix $T$ is not normal, our expressions involve only eigenvalues and eigenvectors with real entries.", "authors": ["Mateusz Kwaśnicki", "Jacek Wszoła"], "published": "2026-06-01T09:46:18Z", "updated": "2026-06-01T09:46:18Z", "primary_category": "math.SP", "categories": ["math.SP", "math.PR"], "abs_url": "https://arxiv.org/abs/2606.01986v1", "pdf_url": "https://arxiv.org/pdf/2606.01986v1", "score": 0, "matched_keywords": [], "coauthors": [], "bucket": "other"}, {"id": "2606.02003v1", "title": "Higher-Order Multifractional Stable Motion: Definition and Fundamental Properties", "abstract": "This paper introduces the $n$-th order multifractional stable motion ($n$-MFSM), a novel stochastic process that simultaneously unifies three key modelling features: heavy-tailed distributions ($α$-stable with $α\\in(1,2]$), time-varying local regularity via a functional Hurst parameter $H(t)\\in(n-1,n)$, and extended scaling behaviour of order $n\\geq1$. No existing framework combines all three. We establish rigorous existence via $L^α$-integrability analysis, derive both moving-average and harmonizable representations with explicit constants, prove local asymptotic self-similarity with complete identification of the limit process, determine the exact pointwise Hölder regularity $α_X(t)=H(t)-1/α$, and characterize long-range dependence through codifference asymptotics. In particular, we obtain the precise decay exponent $(α-1)H_+ + H(s)-n$ and the LRD criterion $(α-1)H_++H(s)<n$, which generalizes the classical condition $H(s)+H_+<1$ for first-order Gaussian multifractional processes and reduces to $αH-1$ for LFSM with constant $H$.", "authors": ["Atef Lechiheb"], "published": "2026-06-01T09:58:52Z", "updated": "2026-06-01T09:58:52Z", "primary_category": "math.PR", "categories": ["math.PR"], "abs_url": "https://arxiv.org/abs/2606.02003v1", "pdf_url": "https://arxiv.org/pdf/2606.02003v1", "score": 0, "matched_keywords": [], "coauthors": [], "bucket": "other"}, {"id": "2606.02056v1", "title": "Special Dirichlet Processes: Structure, Uniqueness and Stability", "abstract": "We introduce the class of \\emph{Special--Dirichlet processes}, consisting of càdlàg adapted processes admitting a decomposition \\[ X=M+Γ, \\] where \\(M\\) is a local martingale and \\(Γ\\) is an adapted càdlàg process with vanishing continuous quadratic variation whose jumps are predictable and \\(\\mathcal F_{s-}\\)-measurable. This class arises naturally from transformations of special semimartingales. Classical results imply that sufficiently regular functions of special semimartingales belong to the broad class of Dirichlet processes. We show that such transformed processes possess substantially more structure: they admit a canonical decomposition in which the predictable jump component is explicitly separated from the martingale component. This yields a refinement of the traditional classification, which previously identified these processes only as Dirichlet processes. We establish uniqueness of the decomposition and prove that the class is stable under a large family of nonsmooth transformations, including primitives of locally bounded functions with at most countably many discontinuities. An explicit Itô-type decomposition is obtained in terms of the martingale jump measure and its compensator. Finally, we investigate stability properties of the canonical decomposition. Under convergence in quadratic variation and Skorokhod \\(J_1\\)-convergence, we prove stability of both the martingale and singular components after transformation. The proof relies on a threshold isolation principle for jump structures, allowing large jumps to be separated from small-jump contributions and yielding convergence of the transformed decompositions.", "authors": ["Philip Kennerberg"], "published": "2026-06-01T10:46:53Z", "updated": "2026-06-01T10:46:53Z", "primary_category": "math.PR", "categories": ["math.PR"], "abs_url": "https://arxiv.org/abs/2606.02056v1", "pdf_url": "https://arxiv.org/pdf/2606.02056v1", "score": 0, "matched_keywords": [], "coauthors": [], "bucket": "other"}, {"id": "2606.02065v1", "title": "Inverting Poisson-Laguerre tessellations", "abstract": "While it is well-known how to compute the cells of a Laguerre tessellation for a given set of weighted generator points, it is not obvious how to invert a Laguerre tessellation. That is, given that one observes a Laguerre tessellation, how can one retrieve the weighted generators corresponding to the observed cells. In this paper, we consider inversion of a class of random Laguerre tessellations known as Poisson-Laguerre tessellations. The weighted generators of observed cells of a Poisson-Laguerre tessellation are of interest because knowledge of these weighted generators is useful for statistical inference of Poisson-Laguerre tessellations. For general Laguerre tessellations we provide a characterization of all configurations of weighted generator points which yield the same Laguerre tessellation. For Poisson-Laguerre tessellations we propose a method for consistent inversion, meaning that as one observes the tessellation through increasing observation windows, a closer approximation of the original weighted generators can be obtained. In a simulation study we examine both performance of the inversion procedure, as well as the use of the obtained approximated weighted generators for nonparametrically estimating the weight distribution function corresponding to a Poisson-Laguerre tessellation.", "authors": ["Thomas van der Jagt", "Geurt Jongbloed", "Martina Vittorietti"], "published": "2026-06-01T10:55:37Z", "updated": "2026-06-01T10:55:37Z", "primary_category": "stat.ME", "categories": ["stat.ME", "math.PR"], "abs_url": "https://arxiv.org/abs/2606.02065v1", "pdf_url": "https://arxiv.org/pdf/2606.02065v1", "score": 0, "matched_keywords": [], "coauthors": [], "bucket": "other"}, {"id": "2606.02180v1", "title": "Universality of the cokernels of random $p$-adic matrices with inhomogeneously balanced columns", "abstract": "In this paper, we prove universality of the distribution of the cokernels of a random $p$-adic matrix with inhomogeneously balanced columns. More precisely, let $u \\ge 0$ be an integer and $A(n)$ be a random $n \\times (n+u)$ matrix over $\\mathbb{Z}_p$ whose $i$-th column is $α_n(i)$-balanced. We prove that if $\\sum_{i=1}^{n+u} \\exp(-εα_n(i)n) \\to 0$ as $n \\to \\infty$ for every $ε>0$, then the cokernels of $A(n)$ converge in distribution, as $n \\to \\infty$, to the same limiting law as the cokernels of Haar-random $n \\times (n+u)$ matrices over $\\mathbb{Z}_p$. This extends a universality theorem of Nguyen and Wood to random $p$-adic matrices with inhomogeneously balanced columns.", "authors": ["Jungin Lee", "Sungjin Park"], "published": "2026-06-01T12:37:15Z", "updated": "2026-06-01T12:37:15Z", "primary_category": "math.NT", "categories": ["math.NT", "math.PR"], "abs_url": "https://arxiv.org/abs/2606.02180v1", "pdf_url": "https://arxiv.org/pdf/2606.02180v1", "score": 0, "matched_keywords": [], "coauthors": [], "bucket": "other"}, {"id": "2606.02311v1", "title": "$γ$-CounterBoost: Optimizing response time tails using job type information only", "abstract": "In a recent paper the $γ$-Boost scheduling policy was shown to minimize the tail of the response time distribution in a light-tailed M/G/1-queue. This policy schedules jobs using a boosted arrival time, defined as the arrival time of a job minus its boost, where the boost of a job depends on its exact job size. The $γ$-Boost policy can also be used when only partial job size information is available, such as the type of an incoming job. In such case the boost $b_i$ of a job depends solely on its type $i$ and $γ$-Boost was shown to optimize the tail among all boost policies, where a boost policy is fully determined by the $b_i$ values. In the partial information setting $γ$-Boost relies on two types of information: job types and arrival times. This paper focuses on the problem of minimizing the tail in a light-tailed M/G/1-queue in the partial job size information setting when the scheduler only makes use of the job types and {\\it does not exploit arrival times}. Prior work showed that in case of $2$ job types the so-called Nudge-$M$ policy minimizes the tail in a large class of scheduling policies. In this paper we introduce the $γ$-CounterBoost policy in the partial information setting with $d \\geq 2$ job types and prove that it minimizes the tail in an even broader class of scheduling policies called Contextual CounterBoost policies. The $γ$-CounterBoost policy reduces to the Nudge-$M$ policy in case of $d=2$ job types.", "authors": ["Nils Charlet", "Benny Van Houdt"], "published": "2026-06-01T14:30:08Z", "updated": "2026-06-01T14:30:08Z", "primary_category": "cs.PF", "categories": ["cs.PF", "math.PR"], "abs_url": "https://arxiv.org/abs/2606.02311v1", "pdf_url": "https://arxiv.org/pdf/2606.02311v1", "score": 0, "matched_keywords": [], "coauthors": [], "bucket": "other"}, {"id": "2606.02464v1", "title": "Using memory to control admission to unobservable queues", "abstract": "We study admission control to an unobservable M/M/1 queue. A memoryless controller can only randomly thin arrivals (random routing, RR). We show that a gated admission (GA) policy, blocking arrivals for a fixed period after each admission, stochastically dominates RR at equal throughput, improving social welfare under any sojourn-based cost. We characterize the welfare-maximizing threshold and define the Price of Forgetting as the welfare ratio. This ratio is unbounded even though the absolute welfare gain stays uniformly bounded.", "authors": ["Refael Hassin", "Liron Ravner"], "published": "2026-06-01T16:37:15Z", "updated": "2026-06-01T16:37:15Z", "primary_category": "math.PR", "categories": ["math.PR"], "abs_url": "https://arxiv.org/abs/2606.02464v1", "pdf_url": "https://arxiv.org/pdf/2606.02464v1", "score": 0, "matched_keywords": [], "coauthors": [], "bucket": "other"}, {"id": "2606.02472v1", "title": "Correlated uniform attachment trees", "abstract": "We introduce and study a new model of correlated uniform attachment (UA) trees, where correlation is sprinkled throughout the time evolution of the process. In this model, two UA trees are grown in parallel, and at each time step a new node is added to each tree, with an edge between it and a uniformly chosen existing vertex in the respective tree. The two choices of attachment are correlated: with probability $α$, the edges attach to nodes with the same time label in both trees, and with probability $1-α$, the choices are made independently. We study fundamental detection and estimation questions for this model, given two \\emph{unlabeled} trees. In our main result, we construct a consistent estimator of the correlation parameter $α$, as the size of the trees goes to infinity. The construction of our statistic relies on two key ideas. First, we use Jordan centrality to identify subsets of vertices of each tree whose intersection has a sufficient number of common early vertices. The second idea is that, across multiple time scales, it is possible to approximately determine the labels of vertices that have attached to these early vertices, using the sizes of fringe subtrees. Our analysis includes novel quantitative bounds on the fraction of early vertices that remain central, which are of independent interest in the network archaeology literature.", "authors": ["Johannes Bäumler", "Miklós Z. Rácz", "Nathan Ross", "Anirudh Sridhar"], "published": "2026-06-01T16:45:18Z", "updated": "2026-06-01T16:45:18Z", "primary_category": "math.PR", "categories": ["math.PR", "cs.SI", "math.ST"], "abs_url": "https://arxiv.org/abs/2606.02472v1", "pdf_url": "https://arxiv.org/pdf/2606.02472v1", "score": 0, "matched_keywords": [], "coauthors": [], "bucket": "other"}, {"id": "2606.02682v1", "title": "Neural Networks and Schramm-Loewner Evolutions", "abstract": "In this manuscript, we explore the application of neural networks to predict the natural parameter $κ\\geq 0$ of Schramm-Loewner Evolution (SLE$_κ$) theory. SLE$_κ$ is a family of random fractal curves that has significant implications in Statistical Mechanics and Conformal Field Theory. This parameter $κ\\geq 0$ plays an important role in the theory as there are models of Planar Statistical Physics that are proven to have SLE as scaling limits as well as others that are conjectured to have this limit for various choices of the parameter $κ\\geq 0$. In addition, there are three different statistical behaviors of the SLE curves as the parameter $κ$ changes in $[0, \\infty).$ Leveraging the powerful pattern recognition capabilities of neural networks, this study aims to develop a predictive model that can estimate the $κ$ parameter with good accuracy.", "authors": ["Neilesh Shrotri", "Vlad Margarint"], "published": "2026-06-01T17:51:45Z", "updated": "2026-06-01T17:51:45Z", "primary_category": "cond-mat.dis-nn", "categories": ["cond-mat.dis-nn", "math.PR"], "abs_url": "https://arxiv.org/abs/2606.02682v1", "pdf_url": "https://arxiv.org/pdf/2606.02682v1", "score": 0, "matched_keywords": [], "coauthors": [], "bucket": "other"}, {"id": "2606.02570v1", "title": "Stochastic completeness for landmark space", "abstract": "We study stochastic completeness for landmark spaces equipped with Riemannian metrics induced by right-invariant metrics on subgroups of the diffeomorphism group of the shape domain. We extend a previous stochastic completeness result, which only covers the case of exactly two landmarks, to landmark spaces with any number of landmarks. This succeeds the characterization of geodesic completeness for landmark spaces with arbitrary numbers of landmarks, and thus finishes the completeness characterization for landmark spaces by covering the stochastic case. The proof makes use of Grigor'yan's volume growth criterion for stochastic completeness, which requires a suitable upper bound for the volume of growing geodesic balls. We obtain quantitative controls for geodesic balls in the landmark space by bounding both its Euclidean size and the rate at which pairwise landmark distances can approach zero. We then combine this with a lower bound on the minimal eigenvalue of the landmark cometric in terms of the Fourier transform of the kernel to yield volume growth bounds sufficient to prove stochastic completeness of landmark spaces for wide classes of kernels, including Matérn kernels.", "authors": ["Karen Habermann", "Stefan Sommer"], "published": "2026-06-01T17:57:02Z", "updated": "2026-06-01T17:57:02Z", "primary_category": "math.PR", "categories": ["math.PR", "math.DG"], "abs_url": "https://arxiv.org/abs/2606.02570v1", "pdf_url": "https://arxiv.org/pdf/2606.02570v1", "score": 0, "matched_keywords": [], "coauthors": [], "bucket": "other"}, {"id": "2606.02864v1", "title": "Ends of stationary metric measure spaces", "abstract": "We prove that stationary random metric measure spaces have 0,1,2 or a Cantor space of ends. This notion includes stationary random graphs, manifolds and discrete subgroups. In the case of surfaces, we classify all possible homeomorphism types, in analogy with the work of Biringer and Raimbault on unimodular Riemannian manifolds. Our approach relies on a general \"no geometric core\" principle and an analysis of finite versus infinite expected return times.", "authors": ["Arie Levit", "Kfir Silman"], "published": "2026-06-01T20:26:36Z", "updated": "2026-06-01T20:26:36Z", "primary_category": "math.DS", "categories": ["math.DS", "math.GN", "math.PR"], "abs_url": "https://arxiv.org/abs/2606.02864v1", "pdf_url": "https://arxiv.org/pdf/2606.02864v1", "score": 0, "matched_keywords": [], "coauthors": [], "bucket": "other"}, {"id": "2606.02886v2", "title": "Scalable Uncertainty Quantification for Extreme Weather Forecasting via Empirical Neural Tangent Kernels", "abstract": "Deep learning weather models now match numerical weather prediction accuracy while running orders of magnitude faster, but produce deterministic forecasts without uncertainty estimates, a critical gap for high-stakes decisions during extreme weather events. This paper proposes Neural Tangent Kernel-based uncertainty quantification (NTK-UQ) using last-layer empirical features. Theoretical analysis predicts that UQ quality is architecture-dependent through two mechanisms. First, a variance collapse mechanism explains when UQ fails: when the eigenvalue truncation rank approaches the effective rank of the feature space, the GP correction term consumes nearly all prior variance, destroying discrimination between tropical cyclones and routine conditions; architectures with concentrated spectra (spectral operators) require aggressive truncation ($k \\leq 10$), while attention-based models tolerate full-rank computation. Second, decomposition performance depends on the non-Gaussian, heavy-tailed structure of extreme weather: Independent Component Analysis exploits higher-order statistics (kurtosis, negentropy) to isolate heavy-tailed extreme-event features, achieving higher discrimination than singular value decomposition, which captures only second-order variance. A data-driven selection rule chooses ICA or SVD from the feature eigenspectrum concentration ratio, correctly prescribing the superior decomposition for all four evaluated architectures. Compared to split conformal prediction (the natural post-hoc baseline), NTK-UQ achieves 31--37\\% sharper prediction intervals at 90\\% coverage, and uniquely produces \\emph{adaptive} intervals that scale with extreme event severity, which conformal prediction cannot achieve by construction. The framework requires no retraining; inference-time uncertainty requires only a single matrix-vector product per sample.", "authors": ["Jose Marie Antonio Miñoza", "Rex Gregor Laylo", "Sebastian C. Ibañez"], "published": "2026-06-01T20:57:06Z", "updated": "2026-06-03T03:56:35Z", "primary_category": "cs.LG", "categories": ["cs.LG", "cs.AI", "cs.CE", "math.PR", "physics.ao-ph"], "abs_url": "https://arxiv.org/abs/2606.02886v2", "pdf_url": "https://arxiv.org/pdf/2606.02886v2", "score": 0, "matched_keywords": [], "coauthors": [], "bucket": "other"}, {"id": "2606.02985v1", "title": "Questions on the structure of random embeddings of $L(\\mathbb{F}_2)$", "abstract": "Motivated by recent developments at the interface of operator algebras and random matrix theory, we propose new conjectures concerning the asymptotic structure of random matrix models of the countable free groups. The first conjecture predicts a random matrix analogue of the Akemann-Ostrand property for free groups, and reveals a succinct approach to recover the Peterson-Thom property for $L(\\mathbb{F}_2)$. The second stronger conjecture is motivated by continuous model theory. It predicts that the \\emph{random} embedding of the free group factor into a matrix ultraproduct is \\emph{existential}. We discuss the interesting relationship between these conjectures.", "authors": ["Ben Hayes", "David Jekel", "Srivatsav Kunnawalkam Elayavalli"], "published": "2026-06-02T00:43:51Z", "updated": "2026-06-02T00:43:51Z", "primary_category": "math.OA", "categories": ["math.OA", "math.FA", "math.LO", "math.PR"], "abs_url": "https://arxiv.org/abs/2606.02985v1", "pdf_url": "https://arxiv.org/pdf/2606.02985v1", "score": 0, "matched_keywords": [], "coauthors": [], "bucket": "other"}, {"id": "2606.03079v1", "title": "Mean Field Limits for Stochastic, Underdamped Reactive Langevin Dynamics Models", "abstract": "We rigorously derive the effective large-population, mean-field dynamics of particle-based reactive Langevin dynamics (PBRLD) models. These models extend particle-based stochastic reaction-diffusion (PBSRD) descriptions by incorporating velocities, inertial effects, and underdamped motion. In Isaacson, Liu, Spiliopoulos, and Yao, SIAP 2026, PBRLD models were formulated and shown to recover Doi volume reactivity PBSRD model in the overdamped limit. In this work we prove convergence of the associated measure-valued stochastic processes, representing species concentration fields on position-velocity phase space, to a deterministic mean-field limit. The limiting equations form a novel system of nonlocal kinetic reaction-diffusion partial integro-differential equations, coupling hypoelliptic transport with reaction terms that retain the spatial and velocity structure of the underlying particle interactions.", "authors": ["Samuel A Isaacson", "Qianhan Liu", "Konstantinos Spiliopoulos"], "published": "2026-06-02T03:10:16Z", "updated": "2026-06-02T03:10:16Z", "primary_category": "math.PR", "categories": ["math.PR", "math-ph"], "abs_url": "https://arxiv.org/abs/2606.03079v1", "pdf_url": "https://arxiv.org/pdf/2606.03079v1", "score": 0, "matched_keywords": [], "coauthors": [], "bucket": "other"}, {"id": "2606.03122v1", "title": "Propagation of support for super-Brownian motion with general branching mechanism", "abstract": "We study the spatial propagation of super-Brownian motion on $\\mathbb{R}^d$ with general critical or subcritical branching mechanisms. Under a Keller-Osserman type integrability condition on the spatially homogeneous branching mechanism, we establish a quantitative upper bound for the short-time probability that the support exits a prescribed neighborhood of its initial support. The estimate has a Gaussian-tail form and is obtained through weighted occupation times, Feynman-Kac representations, singular elliptic boundary blow-up estimates, and comparison principles for nonlinear PDEs. As an application, we derive the compact support property for super-Brownian motions started from compactly supported finite measures. We further extend the argument to spatially dependent branching mechanisms by imposing suitable local lower bounds given by spatially homogeneous mechanisms. This yields a sufficient compact-support criterion expressed in terms of the inverse Keller integral. In particular, our results extend those of Sheu for super-Brownian motions with spatially constant branching mechanisms, and those of Engländer-Pinsky and Ren for super-Brownian motions with stable-like spatially dependent branching mechanisms.", "authors": ["Wenjing Zhang", "Xiaowen Zhou"], "published": "2026-06-02T04:06:35Z", "updated": "2026-06-02T04:06:35Z", "primary_category": "math.PR", "categories": ["math.PR"], "abs_url": "https://arxiv.org/abs/2606.03122v1", "pdf_url": "https://arxiv.org/pdf/2606.03122v1", "score": 0, "matched_keywords": [], "coauthors": [], "bucket": "other"}, {"id": "2606.03182v1", "title": "Logarithmic Sobolev inequality and hypercontractivity for the Navier-Stokes Fokker-Planck operator", "abstract": "The stochastic incompressible Navier-Stokes equations on $\\TT^3$, completed by the fluctuation-dissipation noise, have a Fokker-Planck generator that decomposes into a self-adjoint Ornstein-Uhlenbeck (dissipative) part and an antisymmetric (convective) part. We prove two results about this generator. First, the logarithmic Sobolev inequality holds with the same optimal constant as the pure Ornstein-Uhlenbeck operator, $c_\\mathrm{LSI} = νλ_1$ (where $ν$ is the viscosity and $λ_1$ is the smallest nonzero eigenvalue of the Laplacian on $\\TT^3$), independent of the number of retained Fourier modes. Second, the full semigroup is hypercontractive with the same rate as the Ornstein-Uhlenbeck semigroup. Both results follow from a single structural property: the convective generator is antisymmetric in $L^2(P_\\mathrm{eq})$ (where $P_\\mathrm{eq}$ is the Gibbs measure), and therefore contributes nothing to the Dirichlet form or the $L^q$ norm evolution. The antisymmetry is a consequence of two properties of the incompressible Navier-Stokes nonlinearity: energy conservation and phase-space volume preservation (the Liouville property). These are the same properties that underpin the fluctuation-dissipation theorem for the nonlinear Navier-Stokes equations.", "authors": ["Zhi-Wei Wang", "Samuel L. Braunstein"], "published": "2026-06-02T05:41:40Z", "updated": "2026-06-02T05:41:40Z", "primary_category": "math-ph", "categories": ["math-ph", "cond-mat.stat-mech", "math.AP", "math.PR", "physics.class-ph"], "abs_url": "https://arxiv.org/abs/2606.03182v1", "pdf_url": "https://arxiv.org/pdf/2606.03182v1", "score": 0, "matched_keywords": [], "coauthors": [], "bucket": "other"}, {"id": "2606.03534v1", "title": "Construction and simulation of a path-valued model of dendrite development", "abstract": "Neurons receive information through their dendrites. During development, when synaptic connections are forming, dendrites grow, retract, and branch. The resulting dendritic tree shapes the structure of the broader neural network. Crucially, retraction and branching make it necessary to track whole dendritic paths rather than only their endpoints. While this is handled implicitly in some existing simulations, here we construct an explicitly path-valued stochastic process for dendrite growth. Combining this with a branching process, using ideas from measure-valued branching particle systems, we show that the model produces the typical tree structures of real dendrites. To complement this analytical work, we also outline several methods for numerical simulation, including time discretisations at different temporal scales and an approximation using a dynamic graph. This provides both a more rigorous mathematical framework and more structured simulation methods for modelling dendrite development.", "authors": ["Andrew Nugent", "Karen M. Page", "Alexey Zaikin", "Laura C. Andreae"], "published": "2026-06-02T11:56:38Z", "updated": "2026-06-02T11:56:38Z", "primary_category": "math.PR", "categories": ["math.PR"], "abs_url": "https://arxiv.org/abs/2606.03534v1", "pdf_url": "https://arxiv.org/pdf/2606.03534v1", "score": 0, "matched_keywords": [], "coauthors": [], "bucket": "other"}, {"id": "2606.03549v1", "title": "How Many Trees in a Random Forest? A Revisited Approach with Plateau Search and Optuna Integration", "abstract": "Hyperparameter optimization (HPO) for Random Forest faces a specific difficulty in tuning the number of trees: the predictive score typically improves monotonically with ensemble size, so standard methods such as Tree-structured Parzen Estimator (TPE) and Hyperband require a predefined search range and often drive the estimate toward its right boundary. Early-stopping strategies avoid fixing such a range, but can be sensitive to score noise and prone to premature stopping. To address this, we propose an integrated triplet-based plateau-search algorithm that removes the number of trees from the direct TPE search space and still exploits information accumulated across HPO trials. The method adaptively tracks a near-minimal sufficient ensemble size by monitoring relative changes in the out-of-bag (OOB) score across a triplet of forest sizes and shifting this triplet accordingly. This yields an automated and user-interpretable procedure based on a tolerance parameter. We also provide a theoretical analysis: we relate the proposed relative OOB-score criterion to the gap between the current and limiting scores, and derive an asymptotic variance estimate for the corresponding OOB-based absolute relative difference. Experiments show that the selected number of trees can differ substantially from the common heuristic: for most classical benchmark datasets it is smaller, whereas for some high-dimensional bioinformatics datasets, such as Arcene and Dorothea, it is larger. The source code and reproducible experiments are available at https://github.com/lange-am/rf_plateau_hpo.", "authors": ["Vadim Porvatov", "Andrey Dukhovny", "Andrey Lange"], "published": "2026-06-02T12:10:43Z", "updated": "2026-06-02T12:10:43Z", "primary_category": "cs.LG", "categories": ["cs.LG", "math.PR"], "abs_url": "https://arxiv.org/abs/2606.03549v1", "pdf_url": "https://arxiv.org/pdf/2606.03549v1", "score": 0, "matched_keywords": [], "coauthors": [], "bucket": "other"}, {"id": "2606.03661v1", "title": "Beta-weighted non-local differential operators and related stochastic processes", "abstract": "In this work we introduce a class of non-local differential operators defined through a beta-weighted averaging of the ordinary derivative. We investigate their analytical properties and establish connections with the Caputo and Erdélyi-Kober operators. Differential equations involving the beta-weighted derivative are studied by Mellin transform methods, leading to solutions represented in terms of Barnes G-functions and a new class of G-hypergeometric functions. We also analyze asymptotic properties, Laplace transforms, and the second-order equation involving the sequential beta-weighted derivative. Finally, we present stochastic applications of these results, showing that continuous-time random walks, with waiting times characterized by the beta-weighted derivative, converge to Brownian motions time-changed by a scaled inverse stable subordinator. We compare this anomalous-diffusion model with a time-changed Brownian motion whose one-dimensional distribution solve a heat-type equation with beta-weighted derivative.", "authors": ["L. Beghin", "N. Leonenko", "T. Simon", "J. Vaz"], "published": "2026-06-02T13:47:30Z", "updated": "2026-06-02T13:47:30Z", "primary_category": "math.PR", "categories": ["math.PR"], "abs_url": "https://arxiv.org/abs/2606.03661v1", "pdf_url": "https://arxiv.org/pdf/2606.03661v1", "score": 0, "matched_keywords": [], "coauthors": [], "bucket": "other"}, {"id": "2606.03769v1", "title": "Bregman meets Lévy: Stochastic mirror descent with heavy-tailed noise in continuous and discrete time", "abstract": "We study the robustness of stochastic mirror descent (SMD) under heavy-tailed noise, focusing on whether the method retains its convergence guarantees when run with infinite-variance stochastic gradient input. To address this question in a principled manner, we begin by introducing a continuous-time model of SMD as a stochastic differential equation (SDE) driven by a centered Lévy noise process with finite $p$-th order moments, $1 < p \\leq 2$. This scheme -- which we call the Lévy mirror flow (LMF) -- arises naturally as the scaling limit of SMD in the presence of heavy-tailed noise. In particular, when $p < 2$ -- the heavy noise regime -- the trajectories of LMF generically exhibit jump discontinuities of arbitrary magnitude which, if frequent enough, lead to infinite variance. Nonetheless, despite this highly singular behavior, we show that LMF attains $ε$-optimality within $\\mathcal{O}(ε^{-p/(p-1)})$ time in the convex case, and within $\\mathcal{\\tilde O}(ε^{-1/(p-1)})$ time for (relatively) strongly convex objectives. These guarantees provide a transparent characterization of the impact of frequent long jumps on the convergence of the process, and percolate to a series of matching discrete-time guarantees for several variants of SMD under heavy-tailed noise.", "authors": ["Pierre-Louis Cauvin", "Panayotis Mertikopoulos"], "published": "2026-06-02T15:23:04Z", "updated": "2026-06-02T15:23:04Z", "primary_category": "math.OC", "categories": ["math.OC", "cs.LG", "math.PR"], "abs_url": "https://arxiv.org/abs/2606.03769v1", "pdf_url": "https://arxiv.org/pdf/2606.03769v1", "score": 0, "matched_keywords": [], "coauthors": [], "bucket": "other"}, {"id": "2606.03973v2", "title": "A remark on the majorizing measures theorem for general processes", "abstract": "We show that the lower bound in the majorizing measures theorem holds for a large class of random vectors. Specifically, suppose $X \\sim μ$ is a centered random vector in $\\mathbf{R}^n$ with \\[ C_{\\mathrm{KL}}(μ) = \\sup_{\\substack{θ\\neq η\\\\ θ, η\\in \\mathbf{R}^n}} \\frac{\\mathrm{KL}(μ_θ\\| μ_η)}{\\|θ- η\\|_2^2} < \\infty, \\] where $μ_θ$ denotes the law of the translate $θ+ X$. Then, for every nonempty, bounded $T \\subset \\mathbf{R}^n$, \\[ \\sqrt{C_{\\mathrm{KL}}(μ)}\\, \\mathbf{E}_μ\\Big[\\sup_{t \\in T} \\, \\langle X, t \\rangle \\Big] \\gtrsim γ_2(T), \\] where the righthand side denotes Talagrand's generic chaining functional. This result recovers, as a special case, the lower bound in the majorizing measures theorem for centered Gaussian processes. Our argument critically relies on the rate-distortion integral, recently introduced by J. Liu.", "authors": ["Reese Pathak", "Nikita Zhivotovskiy"], "published": "2026-06-02T17:55:38Z", "updated": "2026-06-03T16:48:08Z", "primary_category": "math.PR", "categories": ["math.PR", "cs.IT", "math.ST"], "abs_url": "https://arxiv.org/abs/2606.03973v2", "pdf_url": "https://arxiv.org/pdf/2606.03973v2", "score": 0, "matched_keywords": [], "coauthors": [], "bucket": "other"}, {"id": "2606.04179v1", "title": "Functional Scaling Limits of Interpolated Correlated Random Walks in Hölder Topology", "abstract": "We prove functional scaling limits for interpolated random walks whose increments are functions of a stationary Gaussian sequence. In this setting, the classical Dobrushin-Major-Taqqu theorem describes the scaling limit when the covariance has a regularly varying, non-summable tail, while the Breuer-Major theorem describes the limit in the summable regime. We strengthen these convergence results to functional convergence in Hölder topology and, in the summable regime, in rough Hölder topology. These stronger topologies are useful because many operations on paths, such as Young integration and solution maps of differential equations, are continuous in (rough) Hölder topology, but not in Skorokhod topology.", "authors": ["Felix Benning", "Ivan Nourdin"], "published": "2026-06-02T19:47:36Z", "updated": "2026-06-02T19:47:36Z", "primary_category": "math.PR", "categories": ["math.PR"], "abs_url": "https://arxiv.org/abs/2606.04179v1", "pdf_url": "https://arxiv.org/pdf/2606.04179v1", "score": 0, "matched_keywords": [], "coauthors": [], "bucket": "other"}, {"id": "2606.04243v1", "title": "Structural properties of the implicit function defined by an integral self-consistency equation", "abstract": "We study the integral equation $\\int_0^m ηρ(η)/(C-η)\\,dη= 1$ with $C>m$, where $ρ$ is a $C^1$ probability density on $[0,M]$ vanishing polynomially at $η=M$. Setting $\\mathcal{I}^+(m) := \\lim_{C \\downarrow m}\\int_0^m ηρ(η)/(C-η)\\,dη$ and $Ω:= \\{m \\in (0,M) : \\mathcal{I}^+(m) > 1\\}$, the equation determines $C$ implicitly as a function of $m$ on $Ω$, and our object of study is the dimensionless ratio $β(m) := C(m)/m$. Writing $h(η) := ηρ(η)$, our main theorem establishes openness of $Ω$, $C^1$-smoothness of $β$, a sign formula identifying $β'(m)$ with a positively-weighted integral of $dh/d\\lnη$, transfer of monotonicity from $h$ to $β$, and existence of an interior critical point of $β$ when $h$ is unimodal and two technical hypotheses hold. Numerically, $β$ has a single critical point in seven log-concave test densities (mostly Beta-type), in support of a separate uniqueness conjecture. A bimodal density that violates both unimodality and log-concavity exhibits three critical points; this shows that dropping the two hypotheses jointly admits multiple critical points, but does not separate their roles.", "authors": ["Ivan Viakhirev"], "published": "2026-06-02T21:45:00Z", "updated": "2026-06-02T21:45:00Z", "primary_category": "cs.SI", "categories": ["cs.SI", "math.PR"], "abs_url": "https://arxiv.org/abs/2606.04243v1", "pdf_url": "https://arxiv.org/pdf/2606.04243v1", "score": 0, "matched_keywords": [], "coauthors": [], "bucket": "other"}, {"id": "2606.04245v1", "title": "Properties of a Special Type of Filtration and its Martingale Criteria", "abstract": "This article investigates the structural properties of stochastic processes relative to a generalized single jump filtration, extending the framework introduced by A.A. Gushchin (2020) to the case of a non-trivial initial $σ$-algebra $\\mathscr{H}$. By leveraging the general theory of processes and optional projection techniques, we establish fundamental measurability criteria for random variables and a complete characterization of stopping times and adapted processes. Furthermore, we derive comprehensive martingale and local martingale criteria, providing necessary and sufficient conditions for the preservation of the martingale property in this extended setting.", "authors": ["Assylliya K. Zhunussova"], "published": "2026-06-02T21:49:46Z", "updated": "2026-06-02T21:49:46Z", "primary_category": "math.PR", "categories": ["math.PR"], "abs_url": "https://arxiv.org/abs/2606.04245v1", "pdf_url": "https://arxiv.org/pdf/2606.04245v1", "score": 0, "matched_keywords": [], "coauthors": [], "bucket": "other"}, {"id": "2606.04377v1", "title": "A comparison principle for Wasserstein PDEs with state- and law-dependent common noise", "abstract": "We prove a comparison principle for a class of second-order Hamilton--Jacobi--Bellman equations on the Wasserstein space whose second-order term is generated by a general common-noise Hessian. The main difficulty is that the relevant second-order direction is induced by a state- and measure-dependent coefficient, so the associated perturbation of the measure is no longer a translation or a fixed state-dependent transformation. We introduce a nonlinear flow of measures and use it to transform the Wasserstein-space equation into an augmented equation on $[0,T]\\times \\mathcal P_2(\\mathbb R)\\times\\mathbb R$, where the general Hessian becomes an ordinary second derivative in the auxiliary variable. The construction may be viewed as a measure-dependent Lamperti transform: it removes the common-noise direction at the level of the equation, but unlike the classical one-dimensional Lamperti transform it permits degeneracy of the coefficient and dependence on the conditional law. We establish the spatial, measure-derivative, and negative-Sobolev estimates for this flow that are needed in the viscosity argument. Under structural assumptions on the transformed Hamiltonian, these estimates yield a Crandall--Ishii type comparison theorem for semicontinuous viscosity sub- and supersolutions. This gives, to the best of our knowledge, the first viscosity comparison framework of this kind for the filtering-driven equations considered here, and opens a new class of second-order PDEs on spaces of measures with state- and law-dependent common-noise directions. As an application, we identify the value function of a controlled stochastic filtering problem with state- and law-dependent common noise as the unique viscosity solution of its dynamic programming equation. We also explain how the same change-of-variable viewpoint applies to Zakai-type Kolmogorov equations on spaces of finite positive measures.", "authors": ["Erhan Bayraktar", "Ibrahim Ekren", "Xihao He", "Xin Zhang"], "published": "2026-06-03T02:50:42Z", "updated": "2026-06-03T02:50:42Z", "primary_category": "math.AP", "categories": ["math.AP", "math.OC", "math.PR"], "abs_url": "https://arxiv.org/abs/2606.04377v1", "pdf_url": "https://arxiv.org/pdf/2606.04377v1", "score": 0, "matched_keywords": [], "coauthors": [], "bucket": "other"}, {"id": "2606.04390v1", "title": "Shortcomings and capacities of real-constrained neural networks in complex spaces", "abstract": "We find the asymptotic ratio between the storage capacities when enforcing real pre-activations in a complex hypothesis class as opposed to complex ones in the same class. Our methods depend on Gardner volume comparisons at critical capacity. Our proof relies on an application of the Harish-Chandra-Itzykson-Zuber (HCIZ) formula, nonstandard in literature. With the HCIZ formula, we may obtain a more robust approximation for the final asymptotic ratio. This strategy is applicable to our work specifically since we integrate over the unitary and orthogonal compact manifolds, facilitated via the Weyl integration formula and the Haar measure.", "authors": ["Andrew Gracyk"], "published": "2026-06-03T03:11:03Z", "updated": "2026-06-03T03:11:03Z", "primary_category": "cs.LG", "categories": ["cs.LG", "cond-mat.dis-nn", "math.PR"], "abs_url": "https://arxiv.org/abs/2606.04390v1", "pdf_url": "https://arxiv.org/pdf/2606.04390v1", "score": 0, "matched_keywords": [], "coauthors": [], "bucket": "other"}, {"id": "2606.05242v1", "title": "Deterministic Envelopes for Tamed SGLD: Decoupling Stochastic-Gradient Noise and Localizing Taming", "abstract": "Stochastic-gradient Langevin algorithms often use tamed denominators to stabilize non-globally Lipschitz drifts. This paper shows that when the denominator depends on the same stochastic-gradient realization as the numerator, the taming step changes the stochastic oracle itself and can create a stationary bias even if the original stochastic gradient is unbiased. We propose a structure-preserving framework for designing tamed denominators. It fixes the denominator before the oracle noise is sampled and uses localized deterministic envelopes to avoid unnecessary taming in typical regions. These kernels keep the stabilizing effect of taming while avoiding the bias introduced by a gradient-dependent denominator. Our theory explains how the stationary error splits into the bias caused by oracle-dependent taming and the remaining error introduced by deterministic stabilization. Within this deterministic-envelope family, the analysis identifies a far-tail condition that explains the limitation of local soft envelopes and motivates a hybrid member: soft in the typical region, but protected by hard-tail control on rare excursions. Experiments confirm the predicted stationary distortions of random denominators, the bias reduction of deterministic-envelope designs, and the stabilizing effect of the hybrid construction.", "authors": ["Yiwei Zhou", "Ziheng Chen"], "published": "2026-06-03T07:23:16Z", "updated": "2026-06-03T07:23:16Z", "primary_category": "stat.ML", "categories": ["stat.ML", "cs.LG", "math.NA", "math.PR"], "abs_url": "https://arxiv.org/abs/2606.05242v1", "pdf_url": "https://arxiv.org/pdf/2606.05242v1", "score": 0, "matched_keywords": [], "coauthors": [], "bucket": "other"}, {"id": "2606.04551v1", "title": "Quasi-birth-and-death processes evolving within trees: Applications to comparative phylogenetics", "abstract": "We consider a quasi-birth-and-process (QBD) that duplicates itself at some fixed times within a tree that contains information about duplication times and potentially partially observed states. We analyse a continuous trait by discretising it to obtain the QBD level variable. Then, the phase variable is used to model the dynamics of the underlying environment. Here, we extend the framework of Soewongsono et al. to enable a more general analysis. We develop an efficient recursive algorithm for computing the likelihood of an observed tree under this model and construct several numerical examples to illustrate its application potential. Through our synthetic data examples, we show a range of potential behaviours that could be modelled with this approach. Further, we apply the framework to two empirical examples from comparative phylogenetics (the evolution of range area and body size traits across a phylogeny of 49 mammals) to gain different insights into the evolution of these continuous traits. In this setting duplication of the QBD represents speciation and continuous trait evolution is modelled in a discretised state space. In our empirical examples, we explore the impact of different parameter choices on the corresponding likelihood of observing a given phylogenetic tree and the observed levels at its tips.", "authors": ["Habtu Kiros Nigus", "Barbara R. Holland", "Malgorzata M. O'Reilly"], "published": "2026-06-03T07:38:16Z", "updated": "2026-06-03T07:38:16Z", "primary_category": "q-bio.PE", "categories": ["q-bio.PE", "math.PR"], "abs_url": "https://arxiv.org/abs/2606.04551v1", "pdf_url": "https://arxiv.org/pdf/2606.04551v1", "score": 0, "matched_keywords": [], "coauthors": [], "bucket": "other"}, {"id": "2606.04573v1", "title": "Layerwise Terminal Discrepancy in Chen's Reverse-Heat Coupling on the Boolean Cube", "abstract": "We isolate a layerwise refinement of the terminal testing-discrepancy step in Chen's perturbed reverse-heat approach~\\cite{Chen2026} to Talagrand's convolution conjecture on the Boolean cube. Built on the joint-filtration martingale formulation of Chen's coupling, and on Chen's approximate monotonicity and conditional squared-score estimates being available in the joint-filtration form stated below, we prove the localized testing estimate \\[ D_E\\le C_τ\\bigl(\\cS_E+\\sqrt{\\cS_E\\,\\Pp(E)}\\bigr), \\qquad E\\in\\mathcal F_θ, \\] where \\(D_E\\) is the localized terminal testing discrepancy and \\(\\cS_E\\) is the stopped perturbative score energy. Applying this estimate to the layers \\(G_r(θ)=\\{r\\le R_θ<r+1\\}\\) replaces the global Cauchy--Schwarz discrepancy cost by the layerwise cost \\[ O_τ\\left(\\fracα{\\sqrt r}+\\frac{α^2}{r}\\right) \\Pp(G_r(θ)), \\qquad α\\simeq\\log\\logη. \\] Under these imported joint-filtration inputs, combining the localized estimate with the time-smoothed anti-concentration profile yields the black-box consequence \\[ μ\\{P_τf>η\\|f\\|_1\\} \\le C_τ\\frac{\\log\\logη}{η\\sqrt{\\logη}}, \\qquad η>e^3, \\] for the Boolean heat semigroup. This makes a $(\\log\\logη)^{1/2}$ improvement over Chen's result.", "authors": ["Yanjin Xiang", "Zhihua Zhang"], "published": "2026-06-03T08:09:22Z", "updated": "2026-06-03T08:09:22Z", "primary_category": "math.FA", "categories": ["math.FA", "cs.DM", "math.PR"], "abs_url": "https://arxiv.org/abs/2606.04573v1", "pdf_url": "https://arxiv.org/pdf/2606.04573v1", "score": 0, "matched_keywords": [], "coauthors": [], "bucket": "other"}, {"id": "2606.04636v1", "title": "A Thomson-type variational principle for diffusion coefficients", "abstract": "We consider reversible interacting particle systems with conserved number of particles. A standard variational formulation describes the diffusion coefficient of such models as the infimum of a certain functional. The purpose of this paper is to derive a new, alternative, variational characterization, as the supremum of another functional. This is a more natural framework when one is interested in obtaining lower bounds on the diffusion coefficient. We present a specific example of a kinetically constrained lattice gas where this variational principle can be applied.", "authors": ["Assaf Shapira"], "published": "2026-06-03T09:07:51Z", "updated": "2026-06-03T09:07:51Z", "primary_category": "math.PR", "categories": ["math.PR", "math-ph"], "abs_url": "https://arxiv.org/abs/2606.04636v1", "pdf_url": "https://arxiv.org/pdf/2606.04636v1", "score": 0, "matched_keywords": [], "coauthors": [], "bucket": "other"}, {"id": "2606.04654v1", "title": "Small-Time Asymptotic Behavior of the Stochastic Landau--Lifshitz--Baryakhtar Equation", "abstract": "We establish a small-time large deviation principle for the stochastic Landau--Lifshitz--Baryakhtar equation using the framework of exponential equivalence. This result characterizes the asymptotic behavior of the solution on very short time scales. In particular, it shows that, as the stochastic thermal fluctuations become small, the magnetization remains exponentially concentrated near its initial state, reflecting the short-time stability of the magnetization dynamics. The associated rate function provides a quantitative measure of deviations from the initial state and the resulting short-time stability.", "authors": ["Utpal Manna", "Sangram Satpathi"], "published": "2026-06-03T09:25:27Z", "updated": "2026-06-03T09:25:27Z", "primary_category": "math.AP", "categories": ["math.AP", "math.PR"], "abs_url": "https://arxiv.org/abs/2606.04654v1", "pdf_url": "https://arxiv.org/pdf/2606.04654v1", "score": 0, "matched_keywords": [], "coauthors": [], "bucket": "other"}, {"id": "2606.04859v1", "title": "Stein's method for the Wishart distribution", "abstract": "In this work, we develop Stein's method for the Wishart distribution on the cone of positive definite matrices. We establish the basic ingredients of a Wishart Stein framework: we derive an extended-generator-based Stein characterization from the Wishart diffusion process, identify the corresponding transition semigroup through the noncentral Wishart law, provide an explicit semigroup representation for the solution of the Stein equation, and obtain regularity estimates for the solution. The new methodology is demonstrated in four applications: (i) an order $n^{-1}$ bound, for smooth test functions, for the Wishart approximation of uncentered group-mean scatter matrices in MANOVA; (ii) a quantitative multivariate Satterthwaite approximation; (iii) local/integrated De Bruijn identities and logarithmic Sobolev inequalities for the Wishart measure; and (iv) Stein's method of moments for the shape and scale parameters, including structured scale estimation.", "authors": ["Gabriel Bailly", "Robert E. Gaunt", "Frédéric Ouimet", "Donald Richards", "Rainer von Sachs"], "published": "2026-06-03T13:26:03Z", "updated": "2026-06-03T13:26:03Z", "primary_category": "math.PR", "categories": ["math.PR", "math.ST", "stat.ME"], "abs_url": "https://arxiv.org/abs/2606.04859v1", "pdf_url": "https://arxiv.org/pdf/2606.04859v1", "score": 0, "matched_keywords": [], "coauthors": [], "bucket": "other"}, {"id": "2606.04950v1", "title": "The Tricomi equation in the hyperbolic half plane under additive space-time Gaussian White Noise perturbation", "abstract": "We study the Cauchy problem for the Tricomi equation perturbed by space-time Gaussian White Noise. To prove existence and uniqueness of the solution, we employ a Fourier transform approach that allows to obtain its representation in terms of certain integrals of the Airy functions. Then, via a careful analysis of the asymptotic behaviour of those integrals, we obtain all the desired properties of the solution, such as square integrability, continuity of its sample paths and stationarity with respect to the space variable. In relation to that stationarity, we also provide the precise description of how the correlation function behaves for small values of the space-lag. We also remark that, in contrast to the findings of the recent paper [11], the properties of the solution to our stochastic Tricomi equation are equivalent to those derived in studying the corresponding problem for the wave operator.", "authors": ["Enrico Bernardi", "Alberto Lanconelli"], "published": "2026-06-03T14:39:15Z", "updated": "2026-06-03T14:39:15Z", "primary_category": "math.PR", "categories": ["math.PR", "math.AP"], "abs_url": "https://arxiv.org/abs/2606.04950v1", "pdf_url": "https://arxiv.org/pdf/2606.04950v1", "score": 0, "matched_keywords": [], "coauthors": [], "bucket": "other"}, {"id": "2606.05266v1", "title": "Sharp Low-Degree Thresholds for Planted-vs-Planted Testing", "abstract": "We establish the first sharp thresholds for low-degree polynomial tests in planted-vs-planted settings, where the goal is to determine with vanishing error which of two structured planted mechanisms generated the observed data. We prove matching low-degree upper and lower bounds for counting communities in the planted submatrix and planted dense subgraph models. The resulting testing threshold coincides, down to the sharp constant, with the known low-degree recovery threshold. In contrast, the task of weak testing, where the goal is to outperform random guessing, does not have a sharp threshold but rather a smooth transition, which we identify. To prove our results, we develop a framework for planted-vs-planted testing that builds on a latent-variable expansion originating in low-degree recovery and employs new methods to identify and prune non-signal contributions.", "authors": ["Anda Skeja", "Daniel Gutiérrez Espinoza", "Fiona Skerman", "Alexander S. Wein"], "published": "2026-06-03T16:28:30Z", "updated": "2026-06-03T16:28:30Z", "primary_category": "cs.LG", "categories": ["cs.LG", "cs.CC", "cs.DS", "math.CO", "math.PR", "math.ST"], "abs_url": "https://arxiv.org/abs/2606.05266v1", "pdf_url": "https://arxiv.org/pdf/2606.05266v1", "score": 0, "matched_keywords": [], "coauthors": [], "bucket": "other"}, {"id": "2606.05089v1", "title": "Quasi-isometric rigidity for random subsets in products of trees", "abstract": "In this article, we prove a rigidity result for quasi-isometric embeddings from a random subset $D$ of the product $\\mathbb{X}$ of two regular trees into $\\mathbb{X}$ itself. This can be seen as an extension of Eskin's quasi-isometric rigidity of higher-rank nonuniform lattices to random subsets. As a consequence, we give a description of the self-quasi-isometric embeddings of a random sample. We also show that two independent samples are almost surely non-quasi-isometric, confirming that such a phenomenon occurs in the higher-rank setting, as suggested by Abért. This result contrasts with the result on quasi-isometric equivalence between random sequences by Basu and Sly.", "authors": ["Zhiqiang Li", "Ranfeng Yu", "Tianyi Zheng"], "published": "2026-06-03T16:54:08Z", "updated": "2026-06-03T16:54:08Z", "primary_category": "math.MG", "categories": ["math.MG", "math.GR", "math.PR"], "abs_url": "https://arxiv.org/abs/2606.05089v1", "pdf_url": "https://arxiv.org/pdf/2606.05089v1", "score": 0, "matched_keywords": [], "coauthors": [], "bucket": "other"}, {"id": "2606.05105v2", "title": "Stochastically evolving ellipsoids with symmetries", "abstract": "We prove that there is a universal constant $c > 0$ such that, along an infinite sequence of dimensions $N$, there are lattice sphere packings in $\\mathbb{R}^N$ of density at least $c N^2 \\log\\log N \\, 2^{-N}$, improving the previous best bound due to Klartag by a $\\log\\log N$ factor. The proof follows Klartag's stochastic ellipsoid evolution process, subject to the cyclotomic symmetries introduced by Venkatesh.", "authors": ["Elisha B. Abuya", "Nihar Gargava", "Yufei Zhao"], "published": "2026-06-03T17:07:07Z", "updated": "2026-06-04T09:51:42Z", "primary_category": "math.MG", "categories": ["math.MG", "math.NT", "math.PR"], "abs_url": "https://arxiv.org/abs/2606.05105v2", "pdf_url": "https://arxiv.org/pdf/2606.05105v2", "score": 0, "matched_keywords": [], "coauthors": [], "bucket": "other"}, {"id": "2606.05324v1", "title": "Optimizing Irreversible Perturbations of the Unadjusted Langevin Algorithm", "abstract": "Irreversible perturbations accelerate the convergence of Langevin dynamics, breaking detailed balance while preserving the invariant measure. The design of optimal irreversible perturbations has been studied in the continuous-time Gaussian setting, but extensions to non-Gaussian target distributions, and the impact of time discretization on the design of optimal perturbations, have not been well understood. Numerical discretizations of Langevin dynamics introduce bias, which is typically exacerbated by irreversible perturbations; handling this interaction demands a joint treatment of acceleration and accuracy. This paper develops a systematic framework for optimizing position-independent irreversible perturbations of the unadjusted Langevin algorithm (ULA). We formulate a constrained optimization problem that simultaneously accounts for mixing efficiency and discretization bias, where the former is characterized by a spectral gap analogue and the latter is quantified via a weighted expected squared jump distance. Within this framework, we derive an explicit characterization of the optimal position-independent irreversible perturbation. Extensive numerical experiments demonstrate that our design yields faster convergence with controlled bias, and improves mean squared estimation errors compared to other choices of irreversible perturbation.", "authors": ["Qianyu Julie Zhu", "Youssef Marzouk", "Konstantinos Spiliopoulos", "Benjamin Zhang"], "published": "2026-06-03T18:10:12Z", "updated": "2026-06-03T18:10:12Z", "primary_category": "math.NA", "categories": ["math.NA", "math.PR", "stat.AP", "stat.CO", "stat.ME"], "abs_url": "https://arxiv.org/abs/2606.05324v1", "pdf_url": "https://arxiv.org/pdf/2606.05324v1", "score": 0, "matched_keywords": [], "coauthors": [], "bucket": "other"}, {"id": "2606.05377v1", "title": "The Clark-Kushner condition for interacting reinforced random walks on finite graphs", "abstract": "We establish the Clark-Kushner condition for a large class of interacting vertex-reinforced random walks on finite graphs, where the transition matrix $Q^i(x)$ of each walk depends on the joint vector $x$ of vertex occupation proportions and may have distinct rows. This allows one to study the dynamics of the vertex occupation measure by using the tools of stochastic approximation theory. However, the standard approach fails because the noise inputs are in our case not a martingale difference: they retain memory of the previous state. Using the solution of the Poisson equation for Markov chains, we decompose the noise into a martingale difference minus the increment of a bounded process -- a structure originating in Gordin's work on limit theorems for stationary processes. The key technical ingredient of our approach is a uniform geometric ergodicity bound derived from the Dobrushin contraction coefficient, which also controls the Lipschitz continuity of the solution of the Poisson equation. Our hypotheses require only that each $Q^i(x)$ be irreducible, aperiodic, and Lipschitz continuous in $x$; in particular, strictly positive entries are not assumed. Our results generalize and simplify previous arguments considered for single self-reinforced vertex-reinforced random walks.", "authors": ["Fernando P. A. Prado", "Rafael A. Rosales"], "published": "2026-06-03T19:26:57Z", "updated": "2026-06-03T19:26:57Z", "primary_category": "math.PR", "categories": ["math.PR"], "abs_url": "https://arxiv.org/abs/2606.05377v1", "pdf_url": "https://arxiv.org/pdf/2606.05377v1", "score": 0, "matched_keywords": [], "coauthors": [], "bucket": "other"}, {"id": "2606.05386v1", "title": "Reinforced random walks with geometric inter-transition times", "abstract": "We consider interacting vertex-reinforced random walks on a finite graph, where each walk transitions at independent geometric random times with parameter $p_i \\in (0,1]$. The transition matrix of walk $i$ takes the form $Q^i(x, p_i) = p_i Π^i(x) + (1-p_i)I$, where $π^i(x)$ is the unique invariant measure, independently of $p_i$. Consequently, the limiting points of the occupation measure $X(n)$ coincide with those of the simultaneous-transition model ($p_i = 1$): the solutions of $x = π(x)$. Verifying almost sure convergence to these points is non-trivial, since the stochastic input $U(n+1)$ is not a martingale difference. We address this by decomposing $U(n)$ into a convergent martingale, a geometrically decaying component $(1-p)U(n-1)$, and a controlled correction, allowing us to verify the Clark-Kushner condition and establish almost sure convergence.", "authors": ["Mirela G. Coelho", "Fernando P. A. Prado"], "published": "2026-06-03T19:43:02Z", "updated": "2026-06-03T19:43:02Z", "primary_category": "math.PR", "categories": ["math.PR"], "abs_url": "https://arxiv.org/abs/2606.05386v1", "pdf_url": "https://arxiv.org/pdf/2606.05386v1", "score": 0, "matched_keywords": [], "coauthors": [], "bucket": "other"}, {"id": "2606.05430v1", "title": "On a random matrix proof of a bipartite Harer-Zagier formula", "abstract": "This work establishes a bipartite generalization of the Harer-Zagier formula using non-Hermitian Random Matrix Theory. More specifically, we use a decomposition of powers of Ginibre eigenvalues as a superposition of independent point processes to identify all coefficients of the generating function of the genus of a surface obtained by a random bipartite pairing of the sides of one polygon with $kM$ sides and $k$ polygons with $M$ sides.", "authors": ["Guillaume Dubach", "Hai An Mai"], "published": "2026-06-03T20:53:00Z", "updated": "2026-06-03T20:53:00Z", "primary_category": "math.PR", "categories": ["math.PR", "math.CO"], "abs_url": "https://arxiv.org/abs/2606.05430v1", "pdf_url": "https://arxiv.org/pdf/2606.05430v1", "score": 0, "matched_keywords": [], "coauthors": [], "bucket": "other"}, {"id": "2606.05475v1", "title": "Reverse inequalities for super-Riesz transforms on graphs with a slow diffusion", "abstract": "In the $D$-dimensional Vicsek graph, we prove that the Riesz-like inequality $ \\|\\nabla f\\|_p \\leq C \\|Δ^γf\\|_p $ holds for every $p\\in(1,\\infty)$ and every $ 0<γ<γ^*(p):=\\frac{1}{D+1}+\\frac{D-1}{D+1}\\,\\frac{1}{p}, $ while it fails whenever $p\\in(1,\\infty)$ and $γ^*(p)<γ<1$. Thus, the validity of the inequality remains open only at the critical exponent $γ=γ^*(p)$. This provides the first example of an $L^p$-bounded ``super-Riesz transform'', namely an operator of the form $\\nabla Δ^{-γ}$ with $γ$ strictly larger than the Euclidean threshold $\\frac12$. To achieve this, we establish a more general result linking the diffusion escape rate and a Poincaré inequality on balls to the validity of the reverse Riesz-like inequality $\\|Δ^γf\\|_p \\leq C \\|\\nabla f\\|_p.$", "authors": ["Joseph Feneuil"], "published": "2026-06-03T21:53:52Z", "updated": "2026-06-03T21:53:52Z", "primary_category": "math.FA", "categories": ["math.FA", "math.PR"], "abs_url": "https://arxiv.org/abs/2606.05475v1", "pdf_url": "https://arxiv.org/pdf/2606.05475v1", "score": 0, "matched_keywords": [], "coauthors": [], "bucket": "other"}, {"id": "2606.05964v2", "title": "Strong Solutions to SDEs with Supercritical Drift Arising in Navigation Problems", "abstract": "We prove strong existence and pathwise uniqueness for two stochastic models of a seeker steering toward a target, written in polar coordinates. In both, the angular drift carries a $\\frac1{r}$-type singularity which belongs to the supercritical regime in $\\mathbb{R}^2$. Standard results for SDEs with singular drift therefore do not apply, and we give a new proof of strong well-posedness based on a pathwise argument. The two models arise from sailboat navigation and proportional navigation. We study the limiting regime in which the stopping radius around the target tends to zero and prove that, despite the singularity at the origin, each system admits a unique strong solution up to the hitting time of the target. These results provide an example of strong well-posedness in a regime where the general theory does not apply.", "authors": ["Carlo Ciccarella"], "published": "2026-06-04T10:03:43Z", "updated": "2026-06-05T11:18:46Z", "primary_category": "math.PR", "categories": ["math.PR"], "abs_url": "https://arxiv.org/abs/2606.05964v2", "pdf_url": "https://arxiv.org/pdf/2606.05964v2", "score": 0, "matched_keywords": [], "coauthors": [], "bucket": "other"}, {"id": "2606.05982v1", "title": "Quantifying Uncertainty In Wide Two-Layer Neural Networks: On The Law Of The Limiting Fluctuation Process", "abstract": "Uncertainty quantification in neural networks prediction is a main issue for usual applications. Our approach seeks at reducing computation costs by directly evaluating uncertainty using PDE's information on the asymptotic variance, rather than the deep ensemble method which may be seen as a Monte Carlo estimation of the prediction, requiring the training of multiple networks. We thus study the law of the limiting process describing the random fluctuations around the mean-field limit of wide two-layer neural networks trained by stochastic gradient descent in a weak-noise regime. Building on a recent trajectorial central limit theorem, in which this limit is characterized as the weak solution of a linear stochastic evolution equation, we identify its law explicitly. More precisely, we show that it is a centered Gaussian process in the dual of a weighted Sobolev space, and we derive a closed covariance representation for the finite-dimensional distributions obtained by testing it against smooth functions. This covariance is expressed through the solution of a backward transport equation with a nonlocal source term, whose coefficients are driven by the mean-field trajectory. As a consequence, by testing against the activation function at a fixed input, we obtain an expression for the limiting variance of the corresponding network-output fluctuations. We illustrate this result numerically on a one-dimensional regression example.", "authors": ["Arnaud Descours", "Arnaud Guillin", "Geoffrey Lacour", "Manon Michel", "Boris Nectoux", "Paul Stos"], "published": "2026-06-04T10:25:23Z", "updated": "2026-06-04T10:25:23Z", "primary_category": "cs.NE", "categories": ["cs.NE", "math.AP", "math.PR"], "abs_url": "https://arxiv.org/abs/2606.05982v1", "pdf_url": "https://arxiv.org/pdf/2606.05982v1", "score": 0, "matched_keywords": [], "coauthors": [], "bucket": "other"}, {"id": "2606.06150v1", "title": "Post-processed frozen-flow methods for the long time sampling of ergodic dynamics on Riemannian manifolds", "abstract": "In this work, we propose a novel intrinsic approach to the approximation of ergodic SDEs on Riemannian manifolds, which include Riemannian Langevin dynamics. In opposition to the standard extrinsic approaches such as penalization methods and projection methods, our methodology does not use embeddings or coordinates and only relies on natural geometric operations: geodesics, parallel transport,... We give a criterion for high order of accuracy for the invariant measure, develop new intrinsic numerical methods designed solely for sampling the invariant measure, and derive high order conditions using a new algebraic operation on exotic Lie-Butcher series. In the spirit of the Leimkuhler-Matthews method, our approach prioritizes long time sampling efficiency over finite time accuracy, and outperforms the previous extrinsic and intrinsic approaches in terms of cost for a given accuracy, which we illustrate with several numerical experiments.", "authors": ["Adrien Busnot Laurent", "Sébastien Macé"], "published": "2026-06-04T13:26:33Z", "updated": "2026-06-04T13:26:33Z", "primary_category": "math.NA", "categories": ["math.NA", "math.CO", "math.DG", "math.PR"], "abs_url": "https://arxiv.org/abs/2606.06150v1", "pdf_url": "https://arxiv.org/pdf/2606.06150v1", "score": 0, "matched_keywords": [], "coauthors": [], "bucket": "other"}, {"id": "2606.06187v1", "title": "How to Study Reflected Brownian Motion in a Quadrant via Kernel Functional Equations? A short survey", "abstract": "We survey a line of works studying semimartingale reflected Brownian motion in a quadrant, covering both the non-degenerate and degenerate settings. Two main situations are emphasized: the recurrent case, where an invariant measure exists, and the transient case, where the central objects are Green's functions (potential measures). These measures typically arise from Kolmogorov forward equations. For transient or killed models one is also interested in the Martin boundary of the process and, consequently, in all positive harmonic functions, which satisfy Kolmogorov backward equations. Depending on the geometry and parameters of the model, these harmonic functions often admit probabilistic interpretations in terms of absorption, escape, or drift to infinity. All these measures and functions are studied through kernel functional equations satisfied by their Laplace transforms. Several ways of solving these equations are reviewed, each leading to different types of results. Following the analytic approach developed for quarter-plane random walks by Fayolle, Iasnogorodski and Malyshev, a key preliminary step is the analytic continuation of the relevant Laplace transforms onto the complex algebraic curve defined by the zero set of the kernel. Carleman boundary value problem techniques then yield explicit contour-integral representations for the Laplace transforms. In special parameter regimes, Tutte's invariant method provides integral-free formulas and a sharp classification of the transforms according to their algebraic-differential complexity. Singularity analysis combined with saddle-point methods carried out on the kernel algebraic curve, produces precise two-dimensional asymptotics. Finally, in the degenerate setting, the compensation approach provides an alternative constructive method, allowing one to build the densities as an infinite series through explicit iterative corrections.", "authors": ["Sandro Franceschi"], "published": "2026-06-04T13:57:52Z", "updated": "2026-06-04T13:57:52Z", "primary_category": "math.PR", "categories": ["math.PR"], "abs_url": "https://arxiv.org/abs/2606.06187v1", "pdf_url": "https://arxiv.org/pdf/2606.06187v1", "score": 0, "matched_keywords": [], "coauthors": [], "bucket": "other"}, {"id": "2606.06193v1", "title": "Peng's Maximum Principle for McKean-Vlasov Stochastic Differential Equations with Common Noise", "abstract": "We study a stochastic optimal control problem for McKean-Vlasov stochastic differential equations (SDEs) with common noise, where the dynamics depend on the conditional law of the state. We derive a stochastic maximum principle of Peng type without imposing convexity assumptions on the control domain. In comparison to the standard McKean-Vlasov case, the maximum principle for the common noise case contains a third adjoint state, which is needed to dualize all second-order Lions derivatives in the Taylor expansion of the cost functional. The additional adjoint state is given by a conditional McKean-Vlasov backward SDE. All three adjoint states together allow for a complete linearization of all contributions in the second-order expansion, including interactions between conditionally independent copies of the first variational process. As part of our analysis, we also prove a general well-posedness result for conditional McKean-Vlasov backward SDEs.", "authors": ["Johan Benedikt Spille", "Wilhelm Stannat"], "published": "2026-06-04T14:00:32Z", "updated": "2026-06-04T14:00:32Z", "primary_category": "math.PR", "categories": ["math.PR", "math.OC"], "abs_url": "https://arxiv.org/abs/2606.06193v1", "pdf_url": "https://arxiv.org/pdf/2606.06193v1", "score": 0, "matched_keywords": [], "coauthors": [], "bucket": "other"}, {"id": "2606.06231v1", "title": "Sensitivity of SDE Solutions to Perturbations of the Diffusion and Drift", "abstract": "We develop a method for bounding the sensitivity of solutions to stochastic differential equations (SDEs) to changes in the drift, $F$, and diffusion, $σ$, by using a combination of information-theoretic uncertainty quantification bounds, functional inequalities, and judiciously chosen coupled auxiliary SDEs. The method is capable of producing non-asymptotic bounds which are well behaved in the $T\\to \\infty$ limit and does not require the perturbations to $F$ and $σ$ to be small. Our approach applies to expectations of both time-averaged and exponentially discounted observables and also produces sensitivity bounds for linear parabolic PDEs. When applied to stationary solutions and Lipschitz observables, our results produce bounds on the $1$-Wasserstein distance between invariant measures which have optimal scaling in each error term. The present method significantly expands on prior information-theoretic SDE sensitivity bounds, which are only applicable to perturbations of the drift.", "authors": ["Jeremiah Birrell"], "published": "2026-06-04T14:37:54Z", "updated": "2026-06-04T14:37:54Z", "primary_category": "math.PR", "categories": ["math.PR"], "abs_url": "https://arxiv.org/abs/2606.06231v1", "pdf_url": "https://arxiv.org/pdf/2606.06231v1", "score": 0, "matched_keywords": [], "coauthors": [], "bucket": "other"}, {"id": "2606.06419v1", "title": "Quantitative eigenvector universality for generalized Wigner matrices", "abstract": "We present a novel approach to eigenvector universality for generalized Wigner matrices. Our main consequences are asymptotic normality of joint eigenvector projections everywhere in the spectrum as well as a quantitative lower bound on the largest entry of an eigenvector. In the case of smooth entries, we are able to obtain joint normality of an explicit growing number of eigenvector projections, and we are also able to obtain an explicit rate of convergence in Kolmogorov distance. This is based on a new analysis of the Dyson vector flow which does not rely on the eigenvector moment flow.", "authors": ["Lucas Benigni"], "published": "2026-06-04T17:26:00Z", "updated": "2026-06-04T17:26:00Z", "primary_category": "math.PR", "categories": ["math.PR", "math-ph"], "abs_url": "https://arxiv.org/abs/2606.06419v1", "pdf_url": "https://arxiv.org/pdf/2606.06419v1", "score": 0, "matched_keywords": [], "coauthors": [], "bucket": "other"}, {"id": "2606.06469v1", "title": "How abundant are good interpolators?", "abstract": "Let $S$ be the set of unit norm linear classifiers $θ\\in \\mathbb{R}^d$ which correctly classify every point of a labeled dataset $(X_i,y_i)_{i=1}^n$, $X_i \\in \\mathbb{R}^d$, $y_i \\in \\{-1,+1\\}$, with a possibly negative margin $κ$ fixed in advance. Under two natural data-generating distributions of the $(X,y)$ pairs -- a Gaussian mixture model and a logistic model with Gaussian features -- and in the proportional regime $n/d \\to α$ with small enough $α$, we establish a large deviation principle on the event that a point $θ$ chosen uniformly at random from $S$ achieves a given generalization error, with high probability over the choice of the data. The associated large deviation rate function is deterministic and describes the proportion, at the exponential scale in $d$, of interpolating classifiers having a given desired performance. As a consequence, we establish the following concentration phenomenon: all but an exponentially small fraction of interpolating classifiers have approximately the same generalization performance given by the unique maximizer of this rate function. We numerically compare this maximizer to the performance of empirical risk minimization by gradient descent and to the performance of a natural linear program, both finding a point in $S$, and deduce that in the overparametrized regime of small $α$, these efficient procedures outperform the vast majority of interpolators, pointing to their nontrivial benign overfitting in this setting.", "authors": ["August Y. Chen", "Ahmed El Alaoui"], "published": "2026-06-04T17:55:10Z", "updated": "2026-06-04T17:55:10Z", "primary_category": "math.ST", "categories": ["math.ST", "cs.LG", "math.PR"], "abs_url": "https://arxiv.org/abs/2606.06469v1", "pdf_url": "https://arxiv.org/pdf/2606.06469v1", "score": 0, "matched_keywords": [], "coauthors": [], "bucket": "other"}, {"id": "2606.06489v1", "title": "The Missing Central Limit Theorems for Local Functionals of Berry's Random Wave Model", "abstract": "Central Limit Theorems for integrals of third degree Hermite polynomials of Berry's random wave model on increasingly large domains are proved in dimensions 2 and 3. These were the missing cases for a complete description of limit theorems for integral functionals of monochromatic random waves based on the Wiener chaos decomposition.", "authors": ["Francesco Grotto"], "published": "2026-06-04T17:59:13Z", "updated": "2026-06-04T17:59:13Z", "primary_category": "math.PR", "categories": ["math.PR"], "abs_url": "https://arxiv.org/abs/2606.06489v1", "pdf_url": "https://arxiv.org/pdf/2606.06489v1", "score": 0, "matched_keywords": [], "coauthors": [], "bucket": "other"}, {"id": "2606.06612v1", "title": "The limit shape and emergence of the Discrete Gaussian level lines", "abstract": "Consider the $(2+1)$D Discrete Gaussian model (ZGFF) on an $L\\times L$ box with a hard floor at height zero and zero boundary conditions, at low temperature. The second author, Martinelli and Sly (2016) showed that the surface has a plateau, filling nearly the full square, at height either $H$ or $H+1$ for an explicit function $H(L)$. In a companion paper, we studied the local laws of the top level lines near the four sides of the box, and showed that after rescaling each by $(L^{2/3-o(1)},L^{1/3-o(1)})$, they converge to a product of Ferrari--Spohn diffusions. Two key features of the top level lines remained unaddressed: their global limit shape, and the critical window marking the transition from a top plateau at height $H$ to one at height $H+1$. These features are intrinsically linked: deriving the global limit of the top level line is needed for determining whether it is preferable to be at height $H$ or $H+1$ near criticality. This work completes this picture as follows. First, we obtain the global limit of the top level lines: for every fixed $n$, the $n$-th from-the-top level line converges in Hausdorff distance to a deterministic shape $\\mathscr{L}_n$ that features the Wulff shape at scale $N_n=L^{1-o(1)}$ near the four corners of the box. Second, we identify, for every $h$, the point of emergence of a macroscopic $h$ level line: the probability of this event is monotone increasing in $L$ (up to a $o(1)$ error), and undergoes a sharp transition from near $0$ to near $1$ in a critical window of width $\\leq L^{1/2+o(1)}$ around a side length $L=L_c^{(h)}$. This transition is discontinuous in that, once a macroscopic level $h$ emerges, it immediately occupies nearly all the box, and the above global and local scaling limits (Wulff, Ferrari--Spohn) hold for it. The new results extend to the $(2+1)$D $|\\nablaφ|^p$-models (ZGFF is the case $p=2$) for every fixed $p> 1$.", "authors": ["Joseph Chen", "Eyal Lubetzky"], "published": "2026-06-04T18:02:01Z", "updated": "2026-06-04T18:02:01Z", "primary_category": "math.PR", "categories": ["math.PR", "math-ph"], "abs_url": "https://arxiv.org/abs/2606.06612v1", "pdf_url": "https://arxiv.org/pdf/2606.06612v1", "score": 0, "matched_keywords": [], "coauthors": [], "bucket": "other"}, {"id": "2606.06655v1", "title": "Letter frequency in shifts of finite type with one forbidden word", "abstract": "This work considers combinatorial and statistical aspects of {\\em{shifts of finite type}}, which are families of words over a finite alphabet which avoid a fixed class of {\\emph{forbidden}} sub-words. The overarching question we are interested in is: how do local statistics of a uniformly random element of the shift space depend on combinatorial features of the forbidden set? We focus on the binary alphabet $\\{0,1\\}$, the class of shift spaces where a single pattern is forbidden, and the average frequency of $1$s (equivalently, the probability of observing $1$ at a given position). In this case, the relevant combinatorial information is encoded by a two-variable auto-correlation polynomial associated to the forbidden word, which we call the {\\em{border polynomial}}. We present several results and examples characterizing the ordering of all words by their letter frequencies: for example, we describe the set of patterns which, when forbidden, cause the frequency of $1$s to increase, decrease, or stay exactly $1/2$. We conjecture that, among forbidden patterns of the same length (except for four exceptional words), the letter frequency is monotone with respect to the number of $1$s in the forbidden word. Our methodologies include novel explicit local injections and bijections, generating function analysis, and a connection with a probabilistic notion of letter frequency.", "authors": ["Miklós Bóna", "Balázs Maga", "Jacob Richey"], "published": "2026-06-04T19:02:27Z", "updated": "2026-06-04T19:02:27Z", "primary_category": "math.CO", "categories": ["math.CO", "math.PR"], "abs_url": "https://arxiv.org/abs/2606.06655v1", "pdf_url": "https://arxiv.org/pdf/2606.06655v1", "score": 0, "matched_keywords": [], "coauthors": [], "bucket": "other"}, {"id": "2606.06657v1", "title": "The massless sine-Gordon model with logarithmic correlations in arbitrary dimension", "abstract": "In this article, we study the sine-Gordon model with logarithmic correlations in arbitrary dimension $d \\ge 1$. The model is defined as a Euclidean field theory whose interaction term in the classical action is \\[ S_{\\mathrm{int}}(\\varphi) := 2z \\int_Λ \\cos(\\sqrtβ\\,\\varphi)\\,\\dx, \\] where $\\varphi$ is a logarithmically correlated Gaussian field on a compact domain $Λ\\subset \\mathbb{R}^d$ that coincides with the Gaussian free field when $d=2$, and where $z \\in \\mathbb{R}$ and $β>0$. We treat both the massive and massless cases, with the main emphasis on the massless regime. We construct the field without imposing boundary conditions, together with its charge and gradient correlation functions, and we show that the partition function is renormalizable. The results are non-perturbative, holding for all $z \\in \\mathbb{R}$. If $d=1$, our results are valid for the full subcritical range $β\\in (0,4π)$ and if $d\\geq 2$, the results are valid for $β\\in (0,(d+1)2π)$. Our analysis is carried out directly in the continuum: we perform renormalization via a scale decomposition and control the partition function by controlling the renormalized potential that arises in this procedure, using the iterated Mayer expansion of Brydges and Kennedy~\\cite{BrKe87a}.", "authors": ["Sami Vihko"], "published": "2026-06-04T19:03:52Z", "updated": "2026-06-04T19:03:52Z", "primary_category": "math-ph", "categories": ["math-ph", "math.PR"], "abs_url": "https://arxiv.org/abs/2606.06657v1", "pdf_url": "https://arxiv.org/pdf/2606.06657v1", "score": 0, "matched_keywords": [], "coauthors": [], "bucket": "other"}, {"id": "2606.06739v1", "title": "The relationship between the transition functions of the labeled and unlabeled versions of the infinitely-many-neutral-alleles diffusion model", "abstract": "The transition function of the unlabeled infinitely-many-neutral-alleles diffusion model, as expressed by Zhou (2015), is derived from the transition function of the labeled infinitely-many-neutral-alleles diffusion model, slightly simplifying the derivation by Feng (2010).", "authors": ["S. N. Ethier"], "published": "2026-06-04T21:53:40Z", "updated": "2026-06-04T21:53:40Z", "primary_category": "math.PR", "categories": ["math.PR"], "abs_url": "https://arxiv.org/abs/2606.06739v1", "pdf_url": "https://arxiv.org/pdf/2606.06739v1", "score": 0, "matched_keywords": [], "coauthors": [], "bucket": "other"}, {"id": "2606.06757v1", "title": "Path-Dependent Ergodic Optimal Control and Backward Stochastic Differential Equations", "abstract": "We investigate a new class of infinite-horizon backward stochastic differential equations for ergodic optimal control where the cost and state dynamics are time and path-dependent. The state process is defined on an unbounded underlying domain and satisfies an extended dissipativity condition. In contrast with the time-homogeneous Markovian setting, the optimal ergodic cost in our framework is characterized by the asymptotic behavior of a deterministic function, rather than by a single real constant. We obtain well-posedness, verification and stability properties, which extend the previous results in the literature on the Markov case.", "authors": ["Xuyang Lin", "Mathieu Lise", "Nizar Touzi"], "published": "2026-06-04T22:39:17Z", "updated": "2026-06-04T22:39:17Z", "primary_category": "math.PR", "categories": ["math.PR", "math.OC"], "abs_url": "https://arxiv.org/abs/2606.06757v1", "pdf_url": "https://arxiv.org/pdf/2606.06757v1", "score": 0, "matched_keywords": [], "coauthors": [], "bucket": "other"}, {"id": "2606.06859v1", "title": "The Rectangular Finite Free Heat Flow", "abstract": "We define and study the rectangular finite free heat flow, a dynamical system on polynomials that plays the role of the heat equation in the setting of rectangular finite free probability. We show several equivalent characterizations of the evolution (including PDE and gradient flow formulations), establish basic properties of the dynamics, and determine the asymptotic distributions of the polynomial roots in the long-time and high-degree limits. We also discuss connections with Calogero-Moser systems and Dunkl processes, and we show that the rectangular finite free heat flow describes the mean curvature expansion of a family of compact Lie group orbits.", "authors": ["Cesar Cuenca", "Colin McSwiggen"], "published": "2026-06-05T03:03:17Z", "updated": "2026-06-05T03:03:17Z", "primary_category": "math.PR", "categories": ["math.PR", "math.CO", "math.DS"], "abs_url": "https://arxiv.org/abs/2606.06859v1", "pdf_url": "https://arxiv.org/pdf/2606.06859v1", "score": 0, "matched_keywords": [], "coauthors": [], "bucket": "other"}, {"id": "2606.07693v1", "title": "Transfer learning for causal forest", "abstract": "Transfer learning addresses the challenge of transfering knowledge from one domain to another. Traditional transfer learning focuses on adapting models trained on a source domain (with a lot of observations) to improve performance on a target domain (with few observations). In this work we consider the case of a model shift and we focus on the transfer learning applied to a causal forest namely HTERF. This causal forest aims to estimate the Conditional Average Treatment Effect (CATE). The approach considered is the offset method presented by Wang (2016) adapted to a causal context. This method relies on the use of intermediate models in order to estimate the offset between source and target distributions. Our main result is a bound on the CATE error of HTERF on target depending on the error of the intermediate models. Simulation studies show the good performances of this approach in different settings on simulations and on a real-world dataset.", "authors": ["Bérénice-Alexia Jocteur", "Véronique Maume-Deschamps", "Pierre Ribereau"], "published": "2026-06-05T07:16:14Z", "updated": "2026-06-05T07:16:14Z", "primary_category": "stat.ML", "categories": ["stat.ML", "cs.LG", "math.PR"], "abs_url": "https://arxiv.org/abs/2606.07693v1", "pdf_url": "https://arxiv.org/pdf/2606.07693v1", "score": 0, "matched_keywords": [], "coauthors": [], "bucket": "other"}, {"id": "2606.07096v1", "title": "Non-selection of Lagrangian trajectories in the zero-noise limit for a class of stochastic regularizations", "abstract": "We prove the lack of selection in the zero-noise limit for solutions to SDEs driven by a divergence-free, Hölder continuous vector field with exponent $α\\in(0,1)$, arbitrarily close to $1$ but fixed. The result applies to a broad class of regularizing additive noises, including fractional Brownian motion and stable Lévy processes. The proof combines pathwise Lagrangian arguments, based on the analysis of the deterministic flows associated to mixing velocity fields, with probabilistic estimates coming from the stochastic sewing lemma. This allows to show that lack of selection happens simultaneously on a large set of initial data, whose complement has arbitrarily small Lebesgue measure.", "authors": ["Lucio Galeati", "Filippo Giovagnini", "Massimo Sorella"], "published": "2026-06-05T09:47:43Z", "updated": "2026-06-05T09:47:43Z", "primary_category": "math.PR", "categories": ["math.PR", "math.AP"], "abs_url": "https://arxiv.org/abs/2606.07096v1", "pdf_url": "https://arxiv.org/pdf/2606.07096v1", "score": 0, "matched_keywords": [], "coauthors": [], "bucket": "other"}, {"id": "2606.07143v1", "title": "Fourier restriction estimates based on $L^q$-dimensions: beyond Stein--Tomas", "abstract": "The well-known Stein--Tomas restriction theorem gives the sharp range of $p$ for which $L^p\\to L^2$ restriction estimates hold for the surface measure on the sphere. This was generalised to arbitrary measures satisfying certain Fourier decay and Frostman conditions by Mockenhaupt, Mitsis, and Bak--Seeger, with the most general version now a fundamental result in harmonic analysis. The Frostman condition essentially asks for uniform control on the measure of small balls and is the endpoint of a continuum of more nuanced conditions which describe the local fluctuations of the measure. This analysis gives rise to the $L^q$-dimensions of a measure and these are a central concept in fractal geometry and a crucial tool in multifractal analysis and the theory of large deviations. In this paper we prove a new Fourier restriction theorem which uses the $L^q$-dimensions instead of the Frostman condition, thus providing a continuum of estimates which recover Stein--Tomas at the endpoint. Our proof gives the endpoint estimate for all values of $q\\in(1,\\infty]$ via Stein's complex interpolation. In particular, in the case $q=\\infty$ this partially resolves a question raised by Bak and Seeger. We explore when our theorem improves on Stein--Tomas, that is, when the range is not optimised at $q=\\infty$, and show that this is the case quite generally, including for certain Mandelbrot cascade measures and measures with multifractal behaviour. On the way to proving our main theorem we obtain a novel description of the $L^q$-dimensions based on certain convolution norms, which may be of interest in its own right.", "authors": ["Marc Carnovale", "Jonathan M. Fraser", "Ana E. de Orellana"], "published": "2026-06-05T10:56:49Z", "updated": "2026-06-05T10:56:49Z", "primary_category": "math.CA", "categories": ["math.CA", "math.DS", "math.FA", "math.MG", "math.PR"], "abs_url": "https://arxiv.org/abs/2606.07143v1", "pdf_url": "https://arxiv.org/pdf/2606.07143v1", "score": 0, "matched_keywords": [], "coauthors": [], "bucket": "other"}, {"id": "2606.07290v1", "title": "Boundary behaviour of the Volterra square-root process", "abstract": "In this work, we study the boundary behaviour of the Volterra square- root process on $\\mathbb{R}_+$. For regular Volterra kernels, we establish a time-dependent Feller condition that guarantees that the process does not hit zero on $[0, T]$, and prove finiteness of negative $p$-moments. For rough kernels that are regularly varying at zero, we show that the process necessarily hits zero with positive probability, and that its law has an atom at the boundary. Finally, for the limit distribution, we show that finiteness of negative moments is determined by the long-time asymptotics of the associated resolvent. In particular, while in the rough case the process has an atom at zero, its limit distribution has finite negative exponential moments. Our proofs are based on comparison principles for Volterra integral equations and generalized Riemann-Liouville fractional equations. The latter provide us with upper and lower bounds for the solution of the associated Volterra Riccati equation, and hence also on the asymptotics of the Laplace transform. As an application, we study the structure of equivalent martingale measures in the Volterra Heston model. For the rough case, we show that equivalent martingale measures exist only under very restrictive assumptions on the drift under the real-world measure.", "authors": ["Martin Friesen", "Stefan Gerhold", "Kristof Wiedermann"], "published": "2026-06-05T14:01:04Z", "updated": "2026-06-05T14:01:04Z", "primary_category": "math.PR", "categories": ["math.PR", "q-fin.MF"], "abs_url": "https://arxiv.org/abs/2606.07290v1", "pdf_url": "https://arxiv.org/pdf/2606.07290v1", "score": 0, "matched_keywords": [], "coauthors": [], "bucket": "other"}, {"id": "2606.07353v1", "title": "The Gaussian structure of a perturbed KPZ", "abstract": "We study the KPZ equation on a circle with an additive spatial perturbation $\\partial_t h=\\tfrac12Δh+\\tfrac12|\\nabla h|^2+ξ+ V$, where $ξ$ is a spacetime white noise and $V$ is a smooth spatial function. When $V=0$, it is well-known that the unique invariant measure is the Brownian bridge. In the presence of the perturbation, we show that the equation admits a unique invariant measure that is absolutely continuous with respect to the Brownian bridge. We further prove the measure has a finite relative entropy with respect to the law of the bridge and that, for any $p\\in(1,\\infty)$, the corresponding Radon-Nikodym derivative belongs to $L^p$, provided that $\\int V^2$ is sufficiently small. The proof uses the discretization and mollification scheme of \\cite{FQ}, together with an application of the log-Sobolev and spectral gap inequalities for the underlying Gaussian measure.", "authors": ["Yu Gu", "Tomasz Komorowski"], "published": "2026-06-05T15:02:13Z", "updated": "2026-06-05T15:02:13Z", "primary_category": "math.PR", "categories": ["math.PR"], "abs_url": "https://arxiv.org/abs/2606.07353v1", "pdf_url": "https://arxiv.org/pdf/2606.07353v1", "score": 0, "matched_keywords": [], "coauthors": [], "bucket": "other"}, {"id": "2606.07417v1", "title": "An optimal local theory for reaction-diffusion equations driven by non-trace-class noise", "abstract": "We study local well-posedness for a class of stochastic reaction-diffusion equations driven by multiplicative, possibly colored, noise. The interaction between rough stochastic forcing and polynomial nonlinearities naturally leads to solutions with low spatial regularity, making the treatment of the nonlinear terms delicate. Our main contribution is a general local existence and uniqueness theory for SPDEs with rough noise and highly irregular initial data. The framework also yields new results in standard noise regimes, including trace-class noise and space-time white noise. We identify the critical initial-data spaces for a wide range of nonlinearities, and we establish instantaneous parabolic regularization, general blow-up criteria, and sufficient conditions for positivity preservation. We apply the abstract theory to several prototypical models, including the stochastic Allen-Cahn, Burgers, Fisher-KPP, and coupled Gray-Scott equations. Finally, in the one-dimensional space-time white-noise setting, we combine our local theory with existing global a priori results in a highly singular regime.", "authors": ["Antonio Agresti", "Fabian Germ", "Mark Veraar"], "published": "2026-06-05T16:10:51Z", "updated": "2026-06-05T16:10:51Z", "primary_category": "math.AP", "categories": ["math.AP", "math.PR"], "abs_url": "https://arxiv.org/abs/2606.07417v1", "pdf_url": "https://arxiv.org/pdf/2606.07417v1", "score": 0, "matched_keywords": [], "coauthors": [], "bucket": "other"}, {"id": "2606.07469v1", "title": "Statistical and Numerical Convergence in Stochastic Equilibrium", "abstract": "This paper sets out the most general computational and econometric implications of the rigorous stochastic equilibrium theory from SELCKE (Staines (2024a)) arXiv:2312.16214. The analytical backbone is the discovery that the system converges geometrically to long-run equilibrium, at a rate given by the greater of the eigenvalue or inverse eigenvalue (from outside) closest to the unit circle and the maximum shock persistence. High-order shocks converge faster. I develop a simulation procedure to test, with asymptotic power, whether stochastic equilibrium exists for a particular model. The fundamental approximation result asserts that, whatever the order of expansion or loss function, the stochastic steady state delivers the most accurate perturbation solution. I also show that super-consistent parameter estimators $O(1/T)$ arise whenever second-order terms vanish. Besides Calvo, I study stochastic equilibrium in two alternative pricing models. Dynamics simplify considerably. I bound the time the impulse response peaks, by the maximum lag in the errors. This lends empirical support to Taylor contracts, although there are issues surrounding unit roots and the strong cost-channel. For menu costs, I demonstrate that the initial price distribution decays away super-exponentially, producing a system equivalent to Calvo with an endogenous reset probability. The impact of idiosyncratic disturbances appears as an additional wedge between actual and efficient output. Blow-up of the objective function at the boundary is proven, with the help of new distributional arguments, so the model meets existing eigenvalue existence conditions for the recursive equilibrium. Along the way, new light is shone on existing theoretical models and statistical procedures.", "authors": ["David Staines"], "published": "2026-06-05T17:22:44Z", "updated": "2026-06-05T17:22:44Z", "primary_category": "econ.EM", "categories": ["econ.EM", "econ.TH", "math.NA", "math.PR"], "abs_url": "https://arxiv.org/abs/2606.07469v1", "pdf_url": "https://arxiv.org/pdf/2606.07469v1", "score": 0, "matched_keywords": [], "coauthors": [], "bucket": "other"}, {"id": "2606.07482v1", "title": "Moments in Rough Bergomi and Boundary Attainment in Rough Heston", "abstract": "We address two open questions in the rough volatility literature. First, we prove finite positive moments for the rough Bergomi price process, and for a wider class of Gaussian Volterra Bergomi models, in the whole subcritical range under negative correlation. More precisely, if \\(ρ\\in[-1,0)\\), then \\(\\E[S_T^p]<\\infty\\) for every \\(0<p<p_ρ\\), where \\(p_{-1}=\\infty\\) and \\(p_ρ=(1-ρ^2)^{-1}\\) for \\(-1<ρ<0\\). For the fractional rough Bergomi kernel, this gives the finite side of the sharp critical moment threshold, complementing the known explosion result above the threshold. Second, we prove that the rough Heston variance process, equivalently the scalar Volterra square-root process with fractional kernel \\(K_α(t)=t^{α-1}/Γ(α)\\) and \\(α\\in(1/2,1)\\), has a positive atom at zero at every positive time. Consequently, zero is hit with positive probability before every positive time horizon. This rules out any Feller-type condition making the zero boundary inaccessible in the fractional rough Heston model.", "authors": ["Arthur Bourdon", "Thibault Jeannin"], "published": "2026-06-05T17:36:26Z", "updated": "2026-06-05T17:36:26Z", "primary_category": "math.PR", "categories": ["math.PR"], "abs_url": "https://arxiv.org/abs/2606.07482v1", "pdf_url": "https://arxiv.org/pdf/2606.07482v1", "score": 0, "matched_keywords": [], "coauthors": [], "bucket": "other"}, {"id": "2606.07729v1", "title": "Large-time behavior and accuracy of the Mean-Field Ensemble Kalman Filter in the Linear Detectable Setting", "abstract": "The ensemble Kalman filter (EnKF), originally developed in the geophysical sciences, is now widely used for state and parameter estimation problems in various domains of application. It may be viewed as a robust, cheap-to-implement, alternative to the optimal, Bayesian, filter. However, despite its empirical successes, theoretical understanding of its properties, in relation to the optimal filter, is in its infancy. In this paper we contribute novel theoretical understanding, studying the behavior of the mean-field limit of the ensemble Kalman filter (MFEnKF) in the linear setting. In this setting the MFEnKF coincides with the Kalman filter itself, for Gaussian initial data. We study the MFEnKF with general, non-Gaussian, initial data. Under the assumptions of nondegeneracy of the signal noise and detectability of the signal-observation pair we make three specific contributions. First, we derive the MFEnKF via a variational approximation of the Bayes update using a covariance-weighted optimal transport metric. Secondly, we use this metric to show that the MFEnKF is a strict contraction towards the subspace of Gaussian measures, giving explicit geometric rates in terms of the covariances, in both discrete and continuous time. Finally, in the continuous-time setting, we deduce a stable form of almost sure accuracy of the MFEnKF: given any pair of (nondegenerate) initial data for the MFEnKF and the optimal filter, any uniformly continuous moments of the two filtering distributions coincide in large time, for almost every observation path.", "authors": ["Franca Hoffmann", "Sangmin Park", "Andrew M. Stuart"], "published": "2026-06-05T17:41:03Z", "updated": "2026-06-05T17:41:03Z", "primary_category": "math.OC", "categories": ["math.OC", "math.AP", "math.PR"], "abs_url": "https://arxiv.org/abs/2606.07729v1", "pdf_url": "https://arxiv.org/pdf/2606.07729v1", "score": 0, "matched_keywords": [], "coauthors": [], "bucket": "other"}, {"id": "2606.07499v1", "title": "Non-asymptotic bounds for quasi-MLE, misspecified models, and dependence under group sequential sampling", "abstract": "We derive asymptotic multivariate normal limits and explicit non-asymptotic normal approximation bounds for group sequential quasi-maximum likelihood estimators under possible model misspecification and within-group dependence. The bounds, obtained using Stein's method, have known constants and apply to a class of dependent-data estimating problems in which the likelihood used for estimation may differ from the true data-generating mechanism. We compute the limiting covariance structure and finite-sample bound explicitly for a Poisson generalized linear mixed model with random group effects and illustrate the results using data from an epilepsy clinical trial.", "authors": ["Julian Aronowitz", "Jay Bartroff"], "published": "2026-06-05T17:53:06Z", "updated": "2026-06-05T17:53:06Z", "primary_category": "math.ST", "categories": ["math.ST", "math.PR"], "abs_url": "https://arxiv.org/abs/2606.07499v1", "pdf_url": "https://arxiv.org/pdf/2606.07499v1", "score": 0, "matched_keywords": [], "coauthors": [], "bucket": "other"}, {"id": "2606.07515v1", "title": "How reliable are LLMs when it comes to playing dice?", "abstract": "We investigate the probabilistic reasoning capabilities of large language models through a controlled benchmarking study on discrete probability problems. We constructed two datasets, respectively a set of standard exercises and a set of counterintuitive exercises, designed to trigger heuristic reasoning, and evaluated 8 state-of-the-art models, each tested with and without Chain-of-Thought prompting. Models achieve an average accuracy of 0.96 on standard problems but only 0.59 on counterintuitive ones. We further provide empirical evidence of token bias: performance drops by over 20% when canonical formulations are replaced by disguised variants. Embedding misleading suggestions in the prompt reduces performance by up to 34%, with no model proving immune. Taken together, the reported findings suggest that current LLMs are not yet genuine probabilistic reasoners, despite their success in advanced mathematical problems.", "authors": ["Luca Avena", "Gianmarco Bet", "Bernardo Busoni"], "published": "2026-06-05T17:59:42Z", "updated": "2026-06-05T17:59:42Z", "primary_category": "cs.CL", "categories": ["cs.CL", "cs.AI", "cs.HC", "math.PR"], "abs_url": "https://arxiv.org/abs/2606.07515v1", "pdf_url": "https://arxiv.org/pdf/2606.07515v1", "score": 0, "matched_keywords": [], "coauthors": [], "bucket": "other"}, {"id": "2606.07516v1", "title": "Counterintuitive problems in discrete probability", "abstract": "This manuscript contains a collection of counterintuitive problems in discrete probability, together with detailed solutions. The dataset was constructed as part of a broader research project investigating the capabilities of the latest-generation Large Language Models (LLMs) in solving discrete probability problems, in order to assess whether LLMs tend to make systematic reasoning errors associated with known cognitive biases. The problems collected here are specifically designed to challenge heuristic reasoning strategies that often lead to intuitively appealing but mathematically incorrect conclusions. The dataset combines several types of problems. Some are adapted from classical probabilistic paradoxes and cognitive-bias literature, while others originate from recreational mathematics sources or were developed by ourselves following similar principles. The primary purpose of this document is to provide a transparent and publicly accessible reference for the problems used in our experimental evaluation of language models, as well as providing detailed human-made solutions. At the same time, we believe that this collection may also prove useful for future research on probabilistic reasoning, cognitive biases, and the evaluation of reasoning capabilities in artificial intelligence systems.", "authors": ["Luca Avena", "Gianmarco Bet", "Bernardo Busoni"], "published": "2026-06-05T17:59:46Z", "updated": "2026-06-05T17:59:46Z", "primary_category": "math.PR", "categories": ["math.PR"], "abs_url": "https://arxiv.org/abs/2606.07516v1", "pdf_url": "https://arxiv.org/pdf/2606.07516v1", "score": 0, "matched_keywords": [], "coauthors": [], "bucket": "other"}, {"id": "2606.07820v1", "title": "A note on rounding fractional matchings with constant-factor strong negative correlation", "abstract": "We describe new dependent-rounding algorithms for bipartite graphs. Given a fractional matching $x$ of graph $G = (U \\cup V, E)$, the algorithms return an integral solution $X$ such that each right-node $v \\in V$ has at most one edge, and where the variables $X_e$ also satisfy broad non-positive correlation properties. In particular, for any edges $e_1, e_2$ sharing a left-node $u \\in U$, the variables $X_{e_1}, X_{e_2}$ have \\emph{strong} negative-correlation, i.e. the expectation of $X_{e_1} X_{e_2}$ is significantly below $x_{e_1} x_{e_2}$. Dependent rounding schemes with these properties have been used for a approximation algorithms for job-scheduling on unrelated machines to minimize weighted completion times, among other applications. Our new algorithm achieves simpler and qualitatively stronger bounds compared to prior algorithms. In particular, we achieve a negative-correlation property $$ \\E[X_{e_1} X_{e_2}] \\leq 0.79751 \\ x_{e_1} x_{e_2}, $$ which is a significant constant-factor improvement over Baveja, Qu & Srinivasan (2023).", "authors": ["David G. Harris"], "published": "2026-06-05T20:05:46Z", "updated": "2026-06-05T20:05:46Z", "primary_category": "cs.DS", "categories": ["cs.DS", "math.PR"], "abs_url": "https://arxiv.org/abs/2606.07820v1", "pdf_url": "https://arxiv.org/pdf/2606.07820v1", "score": 0, "matched_keywords": [], "coauthors": [], "bucket": "other"}, {"id": "2606.07839v1", "title": "Bounds on Spectral Gaps for Non-Reversible Markov Chains with Applications to Temporal Difference Learning", "abstract": "This work is motivated by the analysis of temporal difference algorithms, where stability can be guaranteed by bounding the eigenvalues of an associated matrix derived from a, typically non-reversible, Markov kernel. We generalize the existing sufficient conditions for stability and show that the associated eigenvalues can be bounded in terms of the Dirichlet spectral gap of the Markov kernel. We derive a collection of methods for showing that non-reversible Markov chains have positive spectral gaps. We show that if a Markov chain has positive absolute spectral gap, then it has a positive Dirichlet spectral gap. In the case of discrete-time linear Gaussian systems, we give explicit bounds for both Dirichlet and absolute spectral gaps. Additionally, we present an example of a Markov chain which is $V$-uniformly geometrically ergodic but has zero Dirichlet spectral gap.", "authors": ["Andrew Lamperski"], "published": "2026-06-05T20:58:42Z", "updated": "2026-06-05T20:58:42Z", "primary_category": "math.PR", "categories": ["math.PR"], "abs_url": "https://arxiv.org/abs/2606.07839v1", "pdf_url": "https://arxiv.org/pdf/2606.07839v1", "score": 0, "matched_keywords": [], "coauthors": [], "bucket": "other"}, {"id": "2606.07842v1", "title": "Scars in random waves and the ${\\bf FGF(\\frac12)}$ universality class", "abstract": "We study the large-domain asymptotics of geometric observables in Berry's random wave model on $\\mathbb{R}^d$. We show that, in sharp contrast with the behavior of stationary random fields with absolutely continuous spectral measures, any observable whose fluctuations are asymptotically fully correlated with its second Wiener chaos projection -- under suitable non-degeneracy assumptions -- belongs to a common universality class governed by a fractional Gaussian field with Hurst index $H=\\frac{1-d}{2}$. This class also includes the classical stationary Poisson line process in $\\mathbb{R}^d$. This result is consistent with the description of the filamentary visual patterns -- often described as ``scars'' or ``scarlets'' -- observed in numerical simulations of random waves since the work of Heller, O'Connor and Gehlen (1987), in the precise sense that our findings show that suitable observables of Berry's random wave exhibit fluctuations that, in the large-domain limit, become arbitrarily close to those generated by a Poisson line process. It also suggests that the emergence of linear scar-like patterns in random waves is a phenomenon that persists in any dimension. In the second part of our work, we characterize the scaling limit -- in a distributional sense -- of suitable quadratic transformations of the {\\it Radon--Fourier coefficients} associated with a large class of stationary fields. We show that random waves are characterized by the property that such a scaling limit is a generalized random field obtained by composing white noise on the affine Grassmannian of lines with a dimension-dependent deterministic operator. As an application of our main results, we derive explicit conditions ensuring that quadratic functionals of pullback monochromatic waves on compact Riemannian manifolds exhibit distributional limits in the fractional Gaussian universality class described above.", "authors": ["Louis Gass", "Giovanni Peccati", "Michele Stecconi"], "published": "2026-06-05T21:05:19Z", "updated": "2026-06-05T21:05:19Z", "primary_category": "math.PR", "categories": ["math.PR"], "abs_url": "https://arxiv.org/abs/2606.07842v1", "pdf_url": "https://arxiv.org/pdf/2606.07842v1", "score": 0, "matched_keywords": [], "coauthors": [], "bucket": "other"}, {"id": "2606.07901v1", "title": "Ergodic Theory in Classical and Bayesian Inference", "abstract": "We begin by presenting the mathematical rationale underlying classical deductive inference. We then introduce the foundational ideas of the Bayesian inference framework. Results lying at the interface of Statistics and Ergodic Theory are outlined, providing a theoretical framework applicable to the prediction and analysis of real-world phenomena from random data. This text is expository in nature - no new results are presented; rather, recently published results are described in a didactic manner. Throughout, we work with Hölder equilibrium measures, which encompass a substantially more general class of processes than i.i.d. ones.", "authors": ["Artur O. Lopes"], "published": "2026-06-05T23:22:31Z", "updated": "2026-06-05T23:22:31Z", "primary_category": "math.ST", "categories": ["math.ST", "math.DS", "math.PR"], "abs_url": "https://arxiv.org/abs/2606.07901v1", "pdf_url": "https://arxiv.org/pdf/2606.07901v1", "score": 0, "matched_keywords": [], "coauthors": [], "bucket": "other"}, {"id": "2606.07931v1", "title": "Pointwise Complexity for Gaussian Fields: Upper Envelopes, Algorithmic Lower Bounds, and Separation", "abstract": "We prove a variance-aware pointwise majorizing-measure theorem for centered Gaussian processes. Classical generic chaining characterizes the scalar quantity $\\mathbb E\\sup_{x\\in T}X_x$; the theorem here gives a simultaneous high-probability envelope for the entire field. For an ambient prior $μ$, the envelope at $x$ is governed by a pointwise Fernique-Talagrand functional \\[Φ_μ(x):=\\int_0^{4σ(x)}\\sqrt{\\log\\frac{1}{μ(B_d(x,\\varepsilon))}}\\,d\\varepsilon,\\] together with the corresponding Gaussian tail term. The theorem provides a reusable field-level refinement of classical generic chaining and a Gaussian-process counterpart of pointwise empirical-process bounds for deep neural networks. We also record a Bayesian algorithmic lower envelope from the interactive Fano/data-processing principle. For a known prior $π$, an observation channel, and a concrete estimator $\\widehat t(Y)$, the lower bound is expressed through the exact ghost small-ball mass $\\mathbb E_{Y\\sim Q}π(B_d(\\widehat t(Y),Δ))$, rather than a worst-case covering number. In Gaussian location experiments, comparison decoders convert Bayes location error into lower bounds on decision-aligned Gaussian ranges. We then construct an elementary weighted-basis example separating the usual Fano relaxation for a fixed prior, the Bayesian algorithmic lower envelope, the pointwise Gaussian envelope on the selected subatlas, and the full-class minimax risk/global Gaussian scale. Together, these results show that algorithmic lower bounds provide local-geometric certificates of pointwise complexity for fixed estimators in overparameterized ambient classes, precisely in regimes where classical minimax theory becomes either too coarse or oracle-dependent.", "authors": ["Yunbei Xu"], "published": "2026-06-06T01:50:06Z", "updated": "2026-06-06T01:50:06Z", "primary_category": "math.PR", "categories": ["math.PR", "cond-mat.stat-mech", "cs.IT", "cs.LG", "math.ST"], "abs_url": "https://arxiv.org/abs/2606.07931v1", "pdf_url": "https://arxiv.org/pdf/2606.07931v1", "score": 0, "matched_keywords": [], "coauthors": [], "bucket": "other"}, {"id": "2606.08008v1", "title": "Pathwise structure of the three-dimensional attractive one-point interaction diffusion", "abstract": "We study the pathwise behavior of the three-dimensional attractive one-point interaction diffusion whose law was constructed by Cranston, Koralov, Molchanov and Vainberg, corresponding to the singular Schrödinger Hamiltonian \\[ \\frac12Δ+\\fracβ{2}δ_0, \\qquad β>0. \\] We identify a local stochastic differential equation satisfied by the process away from the origin and use it to construct a natural submartingale whose increasing component in the Doob-Meyer decomposition is supported on the set of times at which the process visits the origin. In particular, we show that the process visits the origin with positive probability and that the law conditioned on avoiding the origin is three-dimensional Wiener measure.", "authors": ["Barkat Mian"], "published": "2026-06-06T06:49:44Z", "updated": "2026-06-06T06:49:44Z", "primary_category": "math.PR", "categories": ["math.PR"], "abs_url": "https://arxiv.org/abs/2606.08008v1", "pdf_url": "https://arxiv.org/pdf/2606.08008v1", "score": 0, "matched_keywords": [], "coauthors": [], "bucket": "other"}, {"id": "2606.08279v1", "title": "Tracks on planar complexes and soficity", "abstract": "We show that every probability-measure-preserving equivalence relation generated by a locally-finite Borel graph with planar connected components is sofic in the sense of Elek--Lippner. In particular, every unimodular random planar graph is sofic. This removes the additional assumptions in the works of Angel--Hutchcroft--Nachmias--Ray and Timár on the soficity of unimodular random planar maps and graphs. To prove this, we investigate Borel simplicial complexes with planar components and approximate them by treeable covering spaces. To construct these coverings, we use a canonical family of tracks on planar simplicial complexes introduced by Dunwoody.", "authors": ["Hiroki Ishikura"], "published": "2026-06-06T17:57:47Z", "updated": "2026-06-06T17:57:47Z", "primary_category": "math.CO", "categories": ["math.CO", "math.DS", "math.GR", "math.PR"], "abs_url": "https://arxiv.org/abs/2606.08279v1", "pdf_url": "https://arxiv.org/pdf/2606.08279v1", "score": 0, "matched_keywords": [], "coauthors": [], "bucket": "other"}, {"id": "2606.08325v1", "title": "Digit Mixing under Polynomial Maps", "abstract": "Let $X=\\sum_{n\\geq1}ξ_n2^{-n} $ be a random number where we model the digits $ξ_n$ as independent Bernoulli random variables with possibly non-identical parameters $p_n=\\mathbb{P}(ξ_n=1)$. For any polynomial $P\\in\\mathbb{R}[X]$ with degree $d\\geq2$, we prove almost sure absolute normality of $P(X)$ under the condition $p_n(1-p_n)\\geq (\\log n)^{Γ(d)} n^{-(d-1)/d}$ for a suitable constant $Γ(d)$ depending only on the degree $d$. Our analysis reveals the sharp power law $n^{-(d-1)/d}$, which is suggested by an elementary heuristics regarding carrier interactions. Our results establish a transition as we further show that the pure critical power law is insufficient, but the precise critical window remains an interesting open problem. As far as we know, this is the first sharp result on digit mixing. We complement our main results by structurally convenient summability criteria, which turns out to be sharp at least for $X^2$, and we formulate a more general conjecture for higher degrees. Our proofs rely on Fourier decay estimates which we obtain by probabilistic argument involving conditioning and non-resonancy estimates combined with a subtle triangularization argument.", "authors": ["Chokri Manai"], "published": "2026-06-06T20:30:50Z", "updated": "2026-06-06T20:30:50Z", "primary_category": "math.PR", "categories": ["math.PR", "math.NT"], "abs_url": "https://arxiv.org/abs/2606.08325v1", "pdf_url": "https://arxiv.org/pdf/2606.08325v1", "score": 0, "matched_keywords": [], "coauthors": [], "bucket": "other"}, {"id": "2606.08683v1", "title": "Exact Fourier dimensions of dyadic Mandelbrot cascades under minimal integrability", "abstract": "We determine the Fourier dimension of the canonical dyadic Mandelbrot cascade on the unit interval under the minimal Kahane--Peyriere condition $W \\ge 0$, $\\mathbb{E}W=1$, $\\mathbb{E}[W\\log_2^+ W]<\\infty$, and $\\mathbb{E}[W\\log_2 W]<1$. Almost surely on non-extinction, $\\dim_F(μ)=\\dim_E(μ)=\\dim_2(μ)=\\sup_{1<q<2}\\max\\{0,2-(2/q)(1+\\log_2\\mathbb{E}[W^q])\\}$, with the convention that the corresponding term is zero when $\\mathbb{E}[W^q]=\\infty$. The proof is carried out in a vector-valued cascade model allowing arbitrary dependence between sibling weights; the classical independent cascade is a special case. This settles the Mandelbrot--Kahane Fourier-dimension problem for canonical Mandelbrot cascades under the minimal integrability condition. We also prove the endpoint theorem for the dyadic Mandelbrot cascade on the unit circle. Under the same assumption, almost surely on non-extinction, $\\dim_F(μ_\\circ)=\\sup_{q>1}\\max\\{0,(q-1-\\log_2\\mathbb{E}[W^q])/q\\}$. The interval and circle formulas have the same light-tail/heavy-tail dichotomy but different obstructions: energy dimension in the interval case, and minimum lower local dimension on the curved support in the circle case. The circle lower bound follows from a finite-moment annular Fourier theorem giving summable annular decay without bounded weights or moments of all orders.", "authors": ["Yin Cai", "Guozheng Cheng", "Xiang Fang", "Menghan Li", "Hongdou Qu", "Chengbo Xiao"], "published": "2026-06-07T15:35:06Z", "updated": "2026-06-07T15:35:06Z", "primary_category": "math.PR", "categories": ["math.PR"], "abs_url": "https://arxiv.org/abs/2606.08683v1", "pdf_url": "https://arxiv.org/pdf/2606.08683v1", "score": 0, "matched_keywords": [], "coauthors": [], "bucket": "other"}, {"id": "2606.08703v1", "title": "Fourier Dimensions of Mandelbrot Cascades under Minimal Integrability", "abstract": "We announce exact Fourier dimension formulae for canonical Mandelbrot cascade measures under the minimal Kahane Peyriere integrability condition. In the dyadic interval setting, the result holds in a balanced vector weight model and gives the equality of Fourier, energy, and L2 dimensions almost surely on non extinction. For the classical scalar dyadic cascade this yields an explicit formula in terms of the moment profile of the weight W. We also announce the corresponding endpoint formula for the canonical cascade on the circle. The note additionally records the canonical base b extension on cubes, where the high dimensional obstruction is the universal Fourier barrier at dimension two.", "authors": ["Xiang Fang"], "published": "2026-06-07T15:59:39Z", "updated": "2026-06-07T15:59:39Z", "primary_category": "math.PR", "categories": ["math.PR"], "abs_url": "https://arxiv.org/abs/2606.08703v1", "pdf_url": "https://arxiv.org/pdf/2606.08703v1", "score": 0, "matched_keywords": [], "coauthors": [], "bucket": "other"}, {"id": "2606.08731v1", "title": "Numerical Analysis on Backward Stochastic Differential Equations by Finite Transposition Method", "abstract": "In this paper, we propose a finite transposition method to solve backward stochastic differential equations (BSDEs, for short). Based on the transposition solution theory for BSDEs, our method offers a promising way of efficiently computing solutions, which can be regarded as an analogous method for BSDEs as the classical finite element method for partial differential equations. Our method has the advantage of easily computable conditional expectations.", "authors": ["Penghui Wang", "Yanqing Wang", "Xu Zhang"], "published": "2026-06-07T17:00:54Z", "updated": "2026-06-07T17:00:54Z", "primary_category": "math.PR", "categories": ["math.PR", "math.NA"], "abs_url": "https://arxiv.org/abs/2606.08731v1", "pdf_url": "https://arxiv.org/pdf/2606.08731v1", "score": 0, "matched_keywords": [], "coauthors": [], "bucket": "other"}, {"id": "2606.08776v1", "title": "Approximation of certain stochastic integrals with anticipating integrands", "abstract": "We study the quantitative approximation of certain stochastic integrals, where we use discrete time approximations under initial enlargement of filtration. It turns out that the approximation rate is in general the same as in the case of no additional information, however, the asymptotic constant improves.", "authors": ["Hannah Geiss", "Stefan Geiss", "Onni Hinkkanen"], "published": "2026-06-07T18:42:15Z", "updated": "2026-06-07T18:42:15Z", "primary_category": "math.PR", "categories": ["math.PR"], "abs_url": "https://arxiv.org/abs/2606.08776v1", "pdf_url": "https://arxiv.org/pdf/2606.08776v1", "score": 0, "matched_keywords": [], "coauthors": [], "bucket": "other"}]};
